return ['domain'=>'lingua-forge','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'nl_NL','project-id-version'=>'Lingua Forge 2.1.0','pot-creation-date'=>'2026-07-21T23:33:36+00:00','po-revision-date'=>'2026-07-05 20:20+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Meertalige routing, volledige meertalige SEO (hreflang, Open Graph, Schema.org, sitemap), en AI-inhoudtools voor WordPress. Taalherkenning, URL-routing, vertaling, inhoudgeneratie, en een volledige SEO-laag — geen bijbehorende plugin nodig.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Vertalen','Lingua Forge — Quick Translate'=>'Lingua Forge — Snelle Vertaling','Informative'=>'Informatief','Persuasive'=>'Overtuigend','Storytelling'=>'Storytelling','Technical'=>'Technisch','Conversational'=>'Conversatie','Permission denied.'=>'Toestemming geweigerd.','Cannot determine target language from slug.'=>'Kan doeltaal niet bepalen uit slug.','Invalid post type.'=>'Ongeldig berichttype.','Invalid or primary language.'=>'Ongeldige of primaire taal.','Template not found or not stored in the database.'=>'Sjabloon niet gevonden of niet opgeslagen in de database.','Template has no content.'=>'Sjabloon heeft geen inhoud.','No internal links found to update.'=>'Geen interne links gevonden om bij te werken.','%d link updated.'=>'%d link bijgewerkt.' . "\0" . '%d links bijgewerkt.','No language-specific template parts found to map.'=>'Geen taal-specifieke sjabloononderdelen gevonden om te koppelen.','No template part references needed updating.'=>'Geen sjabloononderdeelreferenties die bijgewerkt hoeven te worden.','%d part reference updated.'=>'%d onderdeelreferentie bijgewerkt.' . "\0" . '%d onderdeelreferenties bijgewerkt.','Invalid language.'=>'Ongeldige taal.','Template part not found or not stored in the database.'=>'Sjabloononderdeel niet gevonden of niet opgeslagen in de database.','Template part has no content.'=>'Sjabloononderdeel heeft geen inhoud.','No navigation references needed updating.'=>'Geen navigatielinks die bijgewerkt hoeven te worden.','%d navigation reference updated.'=>'%d navigatielink bijgewerkt.' . "\0" . '%d navigatielinks bijgewerkt.','No AI provider configured.'=>'Geen AI-provider geconfigureerd.','Missing pattern name or language.'=>'Ontbrekende patroonnaam of taal.','Pattern not found.'=>'Patroon niet gevonden.','Pattern has no content to translate.'=>'Patroon heeft geen inhoud om te vertalen.','AI provider returned an empty response.'=>'AI-provider gaf een lege reactie.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Patroon vertaald en opgeslagen. Kopieer de inhoud naar je CPT-bericht via de blokeditor Pattern-inserter of gebruik het als startpunt voor een Herbruikbaar Blok.','%d template repaired.'=>'%d sjabloon gerepareerd.' . "\0" . '%d sjablonen gerepareerd.','All template metadata is already up to date.'=>'Alle metadata van sjablonen is al up-to-date.','Invalid template type.'=>'Ongeldig sjabloontype.','Template "%s" already exists.'=>'"%s" bestaat al.','Fix Links'=>'Links corrigeren','Fix Parts'=>'Onderdelen corrigeren','Re-create'=>'Opnieuw maken','"%s" recreated.'=>'"%s" opnieuw gemaakt.','"%s" created.'=>'"%s" gemaakt.','Invalid template part.'=>'Ongeldig sjabloononderdeel.','Template part "%s" already exists.'=>'"%s" bestaat al.','Fix Nav'=>'Navigatie corrigeren','"%1$s" recreated. %2$d template updated.'=>'"%1$s" opnieuw gemaakt. %2$d template bijgewerkt.' . "\0" . '"%1$s" opnieuw gemaakt. %2$d templates bijgewerkt.','"%1$s" created. %2$d template updated.'=>'"%1$s" gemaakt. %2$d sjabloon bijgewerkt.' . "\0" . '"%1$s" gemaakt. %2$d sjablonen bijgewerkt.','Page'=>'Pagina','Single'=>'Enkelvoudig','Search'=>'Zoeken','Search Results'=>'Zoekresultaten','Archive'=>'Archief','Front Page'=>'Voorpagina','Blog Home'=>'Blog startpagina','Single: %s'=>'Enkelvoud: %s','Single %s'=>'Enkelvoud %s','Archive: %s'=>'Archief: %s','%s Archive'=>'%s Archief','No source content found to translate.'=>'Geen broninhoud gevonden om te vertalen.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Vertaald. Bekijk in de Site Editor — interne links, navigatie-URL\'s en sjabloon-slugs worden niet automatisch bijgewerkt.','Navigation not found.'=>'Navigatie niet gevonden.','Navigation has no content to translate.'=>'Navigatie bevat geen inhoud om te vertalen.','"%1$s %2$s" saved.'=>'"%1$s %2$s" opgeslagen.','SEO Analysis'=>'SEO-analyse','Profile'=>'Profiel','Details ↗'=>'Details ↗','/ 100'=>'/ 100','Overall SEO score'=>'Algemene SEO-score','Metric'=>'Metriek','Finding'=>'Vinden','Title'=>'Titel','Meta description'=>'Meta-beschrijving','Word count'=>'Woorden tellen','Reading time'=>'Leestijd','Headings'=>'Koppen','Images'=>'Afbeeldingen','Links'=>'Links','AI Recommendations'=>'AI-aanbevelingen','Run AI Analysis'=>'Voer AI-analyse uit','Analyzing…'=>'Bezig met analyseren…','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Configureer een AI-provider in Instellingen → API-sleutels om AI-aangedreven aanbevelingen mogelijk te maken.','AI analysis failed. Please try again.'=>'AI-analyse mislukt. Probeer het opnieuw.','Suggested title'=>'Voorgestelde titel','Suggested meta description'=>'Voorgestelde meta-beschrijving','Loaded from cache.'=>'Geladen uit cache.','↺ Refresh AI Analysis'=>'↺ AI-analyse vernieuwen','Analyse…'=>'Analyseren…','Analysis request failed. Please try again.'=>'Analyseren aanvraag mislukt. Probeer het opnieuw.','No translation found — analyzed the source language version.'=>'Geen vertaling gevonden — geanalyseerd de bronversie.','Translate page…'=>'Pagina vertalen…','Generate content…'=>'Inhoud genereren…','AI Behaviour Preset'=>'AI Gedragsvoorinstelling','Custom'=>'Aangepast','Global default (%s)'=>'Standaard wereldwijd (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Overschrijft de AI-voorinstelling voor Vertaling en Inhoudsgeneratie op deze pagina. Site-brede aangepaste instructies (Instellingen → Gedrag) worden altijd toegevoegd aan elk verzoek, ongeacht deze selectie.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Overschrijft de AI-voorinstelling voor Vertaling en Inhoudsgeneratie op deze pagina. Alle andere functies gebruiken altijd de wereldwijde voorinstelling.','Close'=>'Sluiten','Translate missing'=>'Vertaling ontbreekt','From'=>'Van','Retranslate'=>'Vertaal opnieuw','Retranslate every other language version from this post. Creates any that are missing and overwrites any that already exist — including the primary language, if this post is a translation.'=>'Vertaal elke andere taalversie van dit bericht opnieuw. Maakt ontbrekende versies aan en overschrijft bestaande versies — inclusief de primaire taal, als dit bericht een vertaling is.','Sync'=>'Synchroniseren','Reassign the correct language-specific template to every existing translation of this post. No AI call and no content changes — free and safe to run any time.'=>'Wijs de juiste taalspecifieke template toe aan elke bestaande vertaling van dit bericht. Geen AI-aanroep en geen inhoudswijzigingen — gratis en veilig om op elk moment uit te voeren.','Template Sync — reassign templates for every translation'=>'Template synchroniseren — templates voor elke vertaling opnieuw toewijzen','TS'=>'TS','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Laatste regelgebaseerde SEO-score. Voer analyse uit in Instellingen → SEO → Analyse om bij te werken.','Translating…'=>'Bezig met vertalen…','Retranslating…'=>'Hervertalen…','Syncing…'=>'Synchroniseren…','This retranslates every other language version of this post from this one — creating any that are missing and overwriting any that already exist (including the primary language, if this post is a translation). This cannot be undone. Continue?'=>'Dit vertaalt elke andere taalversie van dit bericht opnieuw vanuit deze — waarbij ontbrekende versies worden aangemaakt en bestaande versies worden overschreven (inclusief de primaire taal, als dit bericht een vertaling is). Dit kan niet ongedaan worden gemaakt. Doorgaan?','Syncing templates…'=>'Templates synchroniseren…','✓ Done'=>'✓ Gereed','Error'=>'Fout','Navigation posts are translated via the Router tab, not this button.'=>'Navigatieberichten worden vertaald via het Router-tabblad, niet via deze knop.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Het maken van vertalingen voor berichttype "%s" vereist een actieve integratie. Zorg ervoor dat de benodigde integratie is geïnstalleerd en actief.','No %s version found in this translation group.'=>'Geen %s-versie gevonden in deze vertalingsgroep.','Sync from a secondary-language WooCommerce product is disabled by default, since it would overwrite the primary product. Enable it in Settings → Behavior → WooCommerce if you want a translation to be able to become the new source content.'=>'Synchroniseren van een WooCommerce-product in een secundaire taal is standaard uitgeschakeld, omdat het het primaire product zou overschrijven. Schakel dit in via Instellingen → Gedrag → WooCommerce als u wilt dat een vertaling de nieuwe broncontent kan worden.','Sync from a secondary-language post is disabled by default, since it would overwrite the primary post. Enable it in Settings → Behavior → Sync if you want a translation to be able to become the new source content.'=>'Synchroniseren van een bericht in een secundaire taal is standaard uitgeschakeld, omdat het het primaire bericht zou overschrijven. Schakel dit in via Instellingen → Gedrag → Synchroniseren als u wilt dat een vertaling de nieuwe broncontent kan worden.','Skipped — you do not have permission to edit the existing translation.'=>'Overgeslagen — u bent niet gemachtigd om de bestaande vertaling te bewerken.','Creating translations for post type "%s" requires an active integration.'=>'Voor het maken van vertalingen voor het berichttype "%s" is een actieve integratie vereist.','Template Sync can only be run from the primary/source-language post.'=>'Template synchroniseren kan alleen worden uitgevoerd vanuit het primaire/source-taalberichte.','Skipped — you do not have permission to edit this translation.'=>'Overgeslagen — u bent niet gemachtigd om deze vertaling te bewerken.','Translation Caching'=>'Vertaalcache','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge gebruikt twee onafhankelijke cachelagen om overbodige AI API-aanroepen te voorkomen. Gebruik de tabbladen hieronder om elk te inspecteren en te beheren.','API Response Cache'=>'API-antwoordcache','Translation Memory'=>'Vertalingsgeheugen','(disabled)'=>'uitgeschakeld','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Per-bericht cache voor AI-gegenereerde vertalingen, meta-beschrijvingen, uittreksels en inhoud. Items worden automatisch ongeldig gemaakt wanneer de inhoud of AI-provider/model verandert.','Enable API response caching'=>'Schakel API-antwoordcaching in','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'De API Response Cache slaat het ruwe resultaat op van elk AI-verzoek — vertaling, meta-beschrijving, uittreksel en inhoudsgeneratie — op basis van een hash van de invoer (inhoud, taalpaar, provider, model). Schakel uit tijdens promptafstemming of wanneer je wilt dat elk verzoek de AI-provider bereikt. Deactiveren verwijdert niet de cache-invoer — opnieuw inschakelen herstelt ze.','Save'=>'Opslaan','Cached API responses'=>'Gecachte API-antwoorden','API calls saved by cache'=>'API-aanroepen opgeslagen door cache','(avg %.1f hits/entry)'=>'(gemiddeld %.1f hits/entry)','Oldest cached response'=>'Oudste gecachte antwoord','Most recent cached response'=>'Meest recente gecachte antwoord','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Alle gecachte AI-resultaten wissen? Toekomstige verzoeken zullen nieuwe API-aanroepen triggeren totdat de cache opnieuw is opgebouwd.','Clear API Response Cache'=>'Wis API-antwoordcache','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Vertalingscache op blokniveau gedeeld tussen berichten. Wanneer ingeschakeld, worden identieke blokken (zelfde markup, taalpaar en woordenlijst) uit het geheugen gehaald in plaats van de AI opnieuw te bellen. Woordenlijstbewerkingen en wijzigingen in de Compliance-presets maken automatisch de getroffen cachevertalingen ongeldig.','Enable block-level translation cache reuse across posts'=>'Schakel blokniveau vertaalcache-hergebruik over berichten in','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Momenteel overgeslagen voor berichten die blok-opmerking attribuutplaatsaanduidingen gebruiken (wp:details samenvulvelden, enz.) — ze vallen terug op de bestaande enkele-aanvraag vertaalpad.','Cached block translations'=>'Gecachte blokvertalingen','Block translation reuses'=>'Blokvertaling hergebruik','(avg %.1f hits/block)'=>'(gemiddeld %.1f hits/blok)','Oldest cached block'=>'Oudste gecachte blok','Most recent cached block'=>'Meest recente gecachte blok','Approximate size'=>'Geschatte grootte','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Maak het hele Vertaalgeheugen leeg? Toekomstige vertalingen zullen de cache opnieuw opbouwen terwijl ze worden uitgevoerd.','Clear Translation Memory'=>'Vertaalgeheugen wissen','API Response Cache setting saved.'=>'API-responscache-instelling opgeslagen.','Translation Memory setting saved.'=>'Vertaalgeheugeninstelling opgeslagen.','AI cache cleared. %d entry was removed.'=>'AI-cache geleegd. %d item(s) verwijderd.' . "\0" . 'AI-cache geleegd. %d items verwijderd.','Translation Memory cleared. %d cached block was removed.'=>'Vertaalgeheugen gewist. %d gecachte blok is verwijderd.' . "\0" . 'Vertaalgeheugen gewist. %d gecachte blokken zijn verwijderd.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge is een complete meertalige SEO-oplossing. Geen extra SEO-plugin nodig.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Als je een algemene SEO-plugin hebt geïnstalleerd, toont dit paneel hoe LF zich aanpast om dubbele output te voorkomen. Het doel is botsing vermijden — niet samenwerking. LF biedt altijd de meertalige SEO-laag (hreflang, og:locale, inLanguage schema) die kennis vereist van LF\'s taalrouteringsconfiguratie om correct te produceren.','Installed SEO plugins'=>'Geïnstalleerde SEO-plugins','Plugin'=>'Plugin','Status'=>'Status','✓ Active'=>'✓ Actief','— Not detected'=>'— Niet gedetecteerd','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Geen conflicterende SEO-plugins gedetecteerd. Lingua Forge handelt alle SEO-uitvoer onafhankelijk af.','What LF provides — and collision avoidance'=>'Wat LF biedt — en botsingsvermijding','Feature'=>'Functie','LF provides'=>'LF biedt','When another SEO plugin is installed'=>'Wanneer een andere SEO-plugin is geïnstalleerd','Hreflang'=>'Hreflang','Disabled (by setting)'=>'Uitgeschakeld (door instelling)','✓ LF outputs — plugin hreflang suppressed'=>'✓ LF-uitvoer — plugin hreflang onderdrukt','✓ LF outputs'=>'✓ LF-uitvoeren','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF geeft nauwkeurige hreflang voor elke geconfigureerde taal, inclusief x-default. Algemene SEO-plugins hebben geen toegang tot je LF-routeringsconfiguratie en zouden hreflang genereren op basis van onjuiste URL-veronderstellingen. LF onderdrukt hun output via filter om botsingen te voorkomen.','Suppressed: %s.'=>'Onderdrukt: %s.','Open Graph'=>'Open Graph','Disabled (mode setting)'=>'Uitgeschakeld (modusinstelling)','→ Locale tags only — deferring base OG to plugin'=>'→ Alleen locale-tags — basis OG uitstellen tot plugin','→ Locale tags only (manual setting)'=>'→ Alleen locale-tags (handmatige instelling)','✓ LF outputs full OG + Twitter Cards'=>'✓ LF voert volledige OG + Twitter Cards uit','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF voegt altijd og:locale en og:locale:alternate toe — de meertalige OG-signalen die geen algemene SEO-plugin correct kan produceren. Voor de basis OG-set (og:title, og:description, og:image) geeft LF deze weer wanneer er geen andere plugin aanwezig is. Wanneer een SEO-plugin is geïnstalleerd, slaat LF de basisset over om dubbele tags te voorkomen — niet omdat de plugin "beter" is, maar omdat duplicatie geen waarde oplevert.','Schema.org JSON-LD'=>'Schema.org JSON-LD','— Deferred to plugin'=>'— Uitgesteld naar plugin','✓ LF outputs Article / WebPage / WebSite'=>'✓ LF voert Artikel / WebPage / WebSite uit','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF geeft meertalige JSON-LD met inLanguage-aanduidingen die gekoppeld zijn aan de routeringsconfiguratie. Wanneer een SEO-plugin is geïnstalleerd, schakelt LF zijn eigen schema volledig uit: dubbele JSON-LD-grafieken veroorzaken validatiefouten en er is geen eenvoudige manier om een bestaande grafiek aan te vullen.','XML Sitemap'=>'XML Sitemap','✓ Active at /lf-sitemap.xml'=>'✓ Actief op /lf-sitemap.xml','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF genereert zijn eigen sitemap met xhtml:link-alternates voor alle vertaalgroepen. Wanneer een SEO-plugin is geïnstalleerd, genereert het een aparte sitemap — beide bestaan onafhankelijk van elkaar. Dien beide in bij Google Search Console: de sitemap van de SEO-plugin voor inhoudsontdekking, de LF-sitemap voor taalrelatie-signalen.','Canonical tag'=>'Canonical-tag','✓ WP canonical replaced (self-referencing)'=>'✓ WP canonical vervangen (zelfverwijzend)','WP core canonical active (hreflang disabled)'=>'WP-kern canonical actief (hreflang uitgeschakeld)','LF removes the WordPress core canonical tag and replaces it with a self-referencing canonical pointing to the correct language-prefixed URL. When a third-party SEO plugin (Yoast, Rank Math, AIOSEO, SEOPress) is active, LF defers canonical management to that plugin entirely.'=>'LF verwijdert de WordPress-kern canonical tag en vervangt deze door een zelfverwijzende canonical die naar de juiste taal-voorkeur-URL wijst. Wanneer een derde-partij SEO-plugin (Yoast, Rank Math, AIOSEO, SEOPress) actief is, delegeert LF het canonical beheer volledig aan die plugin.','Legacy lf-social-share mu-plugin'=>'Legacy lf-social-share mu-plugin','The lf-social-share mu-plugin is active.'=>'De lf-social-share mu-plugin is actief.','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'De ingebouwde Social Share- en Open Graph-modules van Lingua Forge dekken alle functionaliteit die de mu-plugin biedt, plus meertalige og:locale-ondersteuning. Je kunt de mu-plugin veilig deactiveren.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'OG/Twitter Card-tags: afgehandeld door LF\'s Open Graph-module (SEO → Open Graph & Twitter Cards)','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Social Icons-blok delen: URL\'s: afgehandeld door LF\'s ingebouwde Social Share (SEO → Social Share)','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'kopie/native/automatische JS-acties: afgehandeld door LF\'s social-share.js','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Tijdens activatie behandelt de mu-plugin de basis OG-sets en geeft LF alleen locale tags weer (auto-modus). Verwijdering schakelt LF automatisch over naar volledige OG-modus.','Debug Files'=>'Foutopsporingsbestanden','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Wanneer foutopsporing is ingeschakeld (via de schakelaar hieronder of door LINGUAFORGE_AI_DEBUG te definiëren in wp-config.php), schrijven de vertaal- en FSE-sjabloonvertalingsfuncties hun ruwe AI-prompts en antwoorden naar schijf voor probleemoplossing. Gebruik deze sectie om die output te controleren en te wissen zodra je hebt wat je nodig hebt — de bestanden kunnen snel groeien op grote pagina\'s. Configureer de doelmap via de linguaforge_debug_dir filter.','Debug files cleared. %d file was removed.'=>'Foutopsporingsbestanden gewist. %d bestand is verwijderd.' . "\0" . 'Foutopsporingsbestanden gewist. %d bestanden zijn verwijderd.','Debug logging enabled.'=>'Foutopsporing ingeschakeld.','Debug logging disabled.'=>'Foutopsporing uitgeschakeld.','Debug logging'=>'Foutopsporing','Write AI prompts and responses to disk for troubleshooting'=>'Schrijf AI-prompts en antwoorden naar schijf voor probleemoplossing','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Geforceerd AAN door de LINGUAFORGE_AI_DEBUG-constante in wp-config.php. Verwijder die regel om deze schakelaar hier te regelen.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Geforceerd UIT door de LINGUAFORGE_AI_DEBUG-constante in wp-config.php. Verwijder die regel om deze schakelaar hier te regelen.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Bestanden worden opgeslagen in de onderstaande map. Handig voor het diagnosticeren van vertaalproblemen — zet het uit zodra je hebt wat je nodig hebt zodat de bestanden niet ophopen. Je kunt dit ook forceren vanuit wp-config.php met `define( \'LINGUAFORGE_AI_DEBUG\', true );` wat deze schakelaar overschrijft.','Currently:'=>'Momenteel:','✓ Enabled'=>'✓ Ingeschakeld','✗ Disabled'=>'✗ Uitgeschakeld','Directory'=>'Map','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filter met linguaforge_debug_dir om debug-uitvoer naar een niet-openbare locatie te leiden.','Files'=>'Bestanden','.txt file(s) in the directory'=>'.txt-bestand(en) in de map','Save Debug Setting'=>'Debug-instelling opslaan','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Verwijder alle .txt-bestanden in de debugmap? De map zelf blijft bestaan zodat toekomstige debug-schrijfbeurten nog steeds correct worden opgeslagen.','Clear Debug Files'=>'Debug-bestanden wissen','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge genereert <link rel="alternate" hreflang> tags voor elke geconfigureerde taal op elke pagina, inclusief x-default die naar de brontaal verwijst. Dit is het belangrijkste meertalige SEO-signaal voor Google en andere zoekmachines — er is geen extra SEO-plugin nodig.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Wanneer Yoast SEO, Rank Math, All in One SEO of SEOPress actief is, onderdrukt Lingua Forge automatisch hun hreflang-uitvoer via filter. Algemene SEO-plugins genereren hreflang op basis van een URL-structuur voor één taal en kunnen niet rekening houden met je meertalige routingconfiguratie; de uitvoer van LF is altijd correct.','Hreflang settings saved.'=>'Hreflang-instellingen opgeslagen.','Hreflang output'=>'Hreflang-uitvoer','Output hreflang tags in wp_head'=>'Output hreflang-tags in wp_head','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Uitschakelen alleen voor headless sites of volledig aangepaste hreflang-implementaties. Wanneer uitgeschakeld, verwijdert LF niet langer de WordPress-kern canonical-tag en onderdrukt het niet langer de SEO-plugin hreflang-uitvoer.','Current status'=>'Huidige status','✓ Hreflang active'=>'✓ Hreflang actief','LF is outputting hreflang tags and is replacing the WordPress core canonical with a self-referencing canonical for each language version.'=>'LF voert hreflang-tags uit en vervangt de WordPress core canonical door een zelf-verwijzende canonical voor elke taalversie.','LF is suppressing hreflang output from: %s'=>'LF onderdrukt hreflang-uitvoer van: %s','Save Hreflang Settings'=>'Opslaan Hreflang-instellingen','Language Overrides'=>'Taal Overrides','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Upload gecompileerde .mo-bestanden om strings van derden plugin te overschrijven voor specifieke regio\'s — bijvoorbeeld een aangepaste VikBooking vertaling die "appartement" gebruikt in plaats van "kamer". Bestanden moeten voldoen aan de WordPress-naamgevingsconventie: {textdomain}-{locale}.mo (bijv. vikbooking-ca.mo). Ze worden opgeslagen in de uploads-map en blijven bestaan na plugin-updates.','Override file uploaded successfully.'=>'Overschrijvingsbestand succesvol geüpload.','Override file deleted.'=>'Overschrijvingsbestand verwijderd.','No file was selected.'=>'Geen bestand geselecteerd.','Only .mo files are accepted.'=>'Alleen .mo-bestanden worden geaccepteerd.','The upload failed — please try again.'=>'De upload is mislukt — probeer het opnieuw.','Could not save the file. Check that the uploads folder is writable.'=>'Kon het bestand niet opslaan. Controleer of de uploads-map schrijfbaar is.','Invalid filename.'=>'Ongeldig bestandsnaam.','Security check failed — file path is not permitted.'=>'Beveiligingscontrole mislukt — bestandslocatie is niet toegestaan.','An unknown error occurred.'=>'Er is een onbekende fout opgetreden.','Text domain / locale'=>'Tekstdomein / regio','Size'=>'Grootte','Delete all files for this override (both .mo and .po)?'=>'Verwijder alle bestanden voor deze overschrijving (zowel .mo als .po)?','Delete'=>'Verwijderen','No override files uploaded yet.'=>'Nog geen overschrijvingsbestanden geüpload.','Upload .mo file'=>'Upload .mo-bestand','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Accepteert alleen gecompileerde .mo-bestanden. Bestandsnaam moet het patroon {textdomain}-{locale}.mo volgen. Het uploaden van een bestand met dezelfde naam als een bestaand bestand zal het vervangen.','Upload Override'=>'Upload Overschrijving','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopieer naar Veilige Opslag','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate slaat zijn aangepaste vertalingen op in wp-content/languages/loco/ — een locatie die stilletjes kan worden gewist door een WP-kernupdate, plugin-herinstallatie, of als Loco Translate zelf wordt verwijderd. Bestanden hier kopiëren verplaatst ze naar de Lingua Forge i18n-overrides directory, die door al die gebeurtenissen blijft bestaan en automatisch wordt geladen bij elk verzoek.','File copied to safe storage successfully.'=>'Bestand succesvol gekopieerd naar veilige opslag.','Source file not found.'=>'Bronbestand niet gevonden.','Could not copy the file. Check that the uploads folder is writable.'=>'Kon het bestand niet kopiëren. Controleer of de uploads-map schrijfbaar is.','Invalid file reference.'=>'Ongeldige bestandsreferentie.','Type'=>'Type','✓ In safe storage'=>'✓ In veilige opslag','Copy to safe storage'=>'Kopieer naar veilige opslag','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Nog geen aangepaste Loco Translate-bestanden gevonden. Ze verschijnen hier zodra je een vertaling opslaat in Loco Translate.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge geeft Open Graph- en Twitter Card-meta-tags uit zodat gedeelde URL\'s de juiste taal, titel, beschrijving en afbeelding tonen op sociale platforms.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'In tegenstelling tot hreflang — waar LF altijd andere plugins overschrijft omdat zij je meertalige configuratie niet kennen — is Open Graph anders: Yoast, Rank Math en soortgelijke plugins genereren al correcte OG-tags voor je inhoud. Ze dupliceren voegt geen waarde toe. In de automatische modus detecteert LF actieve SEO-plugins en voegt alleen toe wat zij niet kunnen bieden: og:locale (huidige taal) en og:locale:alternate (alle andere geconfigureerde talen).','Open Graph settings saved.'=>'Open Graph-instellingen opgeslagen.','Open Graph output'=>'Open Graph-uitvoer','Output Open Graph tags in wp_head'=>'Output Open Graph-tags in wp_head','Output mode'=>'Output-modus','Auto (recommended)'=>'Auto (aanbevolen)','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Detecteer actieve SEO-plugins (Yoast, Rank Math, etc.) tijdens het uitvoeren. Geef alleen og:locale + og:locale:alternate weer wanneer een andere plugin al de volledige OG-set uitzendt; geef de volledige set weer wanneer er geen wordt gedetecteerd.','Locale only'=>'Alleen locale','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Altijd alleen og:locale en og:locale:alternate uitzenden. Gebruik wanneer een andere plugin of thema de volledige OG-set afhandelt.','Full'=>'Volledig','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Altijd de volledige OG + Twitter Card set uitzenden, ongeacht andere plugins. Gebruik alleen als geen andere plugin OG-tags uitzendt.','Disabled'=>'Uitgeschakeld','Do not output any OG tags.'=>'Geen OG-tags weergeven.','Default OG image'=>'Standaard OG-afbeelding','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'Fallback-afbeeldings-URL die wordt gebruikt wanneer een pagina geen uitgelichte afbeelding, site-logo of site-icoon heeft. Getoond in sociale previews voor archieven, de blogindex en elke enkelvoudige pagina zonder miniatuur.','— Disabled'=>'— Uitgeschakeld','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Actief — alleen locale-tags (og:locale, og:locale:alternate)','✓ Active — full OG + Twitter Cards'=>'✓ Actief — volledige OG + Twitter Cards','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Legacy lf-social-share mu-plugin gedetecteerd. LF stelt de basis OG-set uit naar de mu-plugin en geeft alleen og:locale + og:locale:alternate weer. Je kunt de mu-plugin deactiveren — LF\'s ingebouwde Social Share (SEO → Social Share-tab) en Open Graph dekken dezelfde functionaliteit.','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'SEO-plugin(s) gedetecteerd: %s. LF geeft alleen og:locale en og:locale:alternate weer; de gedetecteerde plugin behandelt de volledige OG-set.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Geen externe OG-plugin gedetecteerd. LF geeft de volledige OG + Twitter Card set uit.','Save Open Graph Settings'=>'Opslaan Open Graph-instellingen','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge geeft Schema.org JSON-LD gestructureerde gegevens uit zodat zoekmachines je inhoudstype, taal en metadata begrijpen. Dit is de belangrijkste manier om inLanguage-aanduidingen voor meertalige inhoud te communiceren aan Google en andere crawlers.','Schema output deferred.'=>'Schema-uitvoer uitgesteld.','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s is actief en geeft al JSON-LD van Schema.org weer. Lingua Forge heeft de eigen schema-uitvoer uitgeschakeld om conflicterende grafieken te voorkomen. In tegenstelling tot Open Graph — waar LF og:locale toevoegt boven de uitvoer van een andere plugin — kan schema niet schoon worden aangevuld: dubbele of overlappende JSON-LD-grafieken veroorzaken validatiefouten. Schakel schema-uitvoer uit in de gedetecteerde plugin als je wilt dat LF gestructureerde gegevens afhandelt.','Schema.org settings saved.'=>'Schema.org-instellingen opgeslagen.','Schema.org output'=>'Schema.org-uitvoer','Output Schema.org JSON-LD in wp_head'=>'Output Schema.org JSON-LD in wp_head','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Vergrendeld — een conflicterende SEO-plugin is actief. Zie de bovenstaande melding.','Article / WebPage'=>'Artikel / Webpagina','Output Article or WebPage schema on singular posts and pages'=>'Output Artikel- of WebPage-schema op enkelvoudige berichten en pagina\'s','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Blogberichten gebruiken Artikel; alle andere berichttypen en pagina\'s gebruiken WebPage. Bevat kop, beschrijving, inLanguage, url, datumPublicatie, datumWijziging, afbeelding en uitgever.','WebSite'=>'WebSite','Output WebSite schema on the front page and blog index'=>'Output WebSite schema op de voorpagina en blogindex','Includes site name, url, and inLanguage.'=>'Bevat sitenaam, url en inLanguage.','Product'=>'Product','Output Product schema on WooCommerce product pages'=>'Output Product-schema op WooCommerce-productpagina\'s','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Bevat naam, beschrijving, inLanguage, url, afbeelding en een Aanbieding met prijs, prijsvaluta en beschikbaarheid. Prijs en beschikbaarheid komen van het bronproduct (gedeeld voorraadmodel).','Currently emitting'=>'Momenteel wordt uitgezonden','Article / WebPage — all singular posts and pages'=>'Artikel / Webpagina — alle enkelvoudige berichten en pagina\'s','WebSite — front page / blog index'=>'WebSite — startpagina / blogindex','Product — WooCommerce product pages'=>'Product — WooCommerce productpagina\'s','Nothing — all types disabled'=>'Niets — alle types uitgeschakeld','Save Schema.org Settings'=>'Opslaan Schema.org-instellingen','Blog / Editorial'=>'Blog / Redactie','Product / eCommerce'=>'Product / eCommerce','Landing / Short-form'=>'Landingspagina / Kort formaat','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filter op taal en berichttype, blader door je inhoud en klik op Analyse op elk item om een SEO-controle uit te voeren op basis van regels — titelgrootte, meta-beschrijving, woordtelling, kopstructuur, afbeeldings-Alt-dekking en interne links.','Treat H2 as H1 equivalent'=>'H2 als H1 behandelen','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Inschakelen wanneer je thema de berichttitel weergeeft als een H2 in plaats van een H1 (veelvoorkomend bij sommige blokthema\'s). De analyzer haalt de gerenderde pagina op en als er geen H1 wordt gevonden maar wel een H2, promoot hij de eerste H2 naar H1 voor de score.','Save analysis settings'=>'Analyse-instellingen opslaan','Per-Post Analysis'=>'Per-bericht Analyse','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Selecteer een bericht en voer een gedetailleerde SEO-audit uit om per-metrische resultaten en een score voor dat specifieke item te zien.','Language'=>'Taal','source'=>'bron','All types'=>'Alle types','Load content'=>'Inhoud laden','Batch Analysis'=>'Batchanalyse','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Voer een volledige SEO-audit uit op alle gepubliceerde berichten voor één of alle actieve talen. Scores worden per bericht opgeslagen en weergegeven in de badge in de kolom Taal in de berichtlijst.','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'WooCommerce-systeempagina\'s (Winkel, Winkelwagen, Afrekenen, Mijn account) zijn uitgesloten — hun inhoud wordt beheerd door WooCommerce en kan niet worden verbeterd via SEO-bewerkingen.','Post type'=>'Berichttype','Default profile'=>'Standaardprofiel','— Auto-detect —'=>'— Automatisch detecteren —','Analyse all languages'=>'Analyseer alle talen','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'Auto-detect toewijzingen: WooCommerce-producten → Productprofiel; de statische startpagina → Landingsprofiel; alles andere → Blogprofiel. Kies een specifiek profiel om dit voor alle berichten te overschrijven.','%d post'=>'%d bericht' . "\0" . '%d berichten','Last run: %s ago'=>'Laatste keer uitgevoerd: %s geleden','Never run'=>'Nooit rennen','avg'=>'gemiddeld','(partial)'=>'(gedeeltelijk)','Analyse'=>'Analyse','(no title) #%d'=>'(geen titel) #%d','Invalid post ID.'=>'Ongeldige bericht-ID.','Post not found or not published.'=>'Bericht niet gevonden of niet gepubliceerd.','~%d min read'=>'~%d min lezen' . "\0" . '~%d min lezen','No title set.'=>'Geen titel ingesteld.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'Titel is %1$d tekens — kan worden afgekapt in SERPs (streef naar minder dan %2$d).','Title is only %d chars — aim for at least 10 characters.'=>'Titel is slechts %d tekens — streef naar minstens 10 tekens.','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Enkele woorden titel (%d tekens) — het toevoegen van een tweede woord verbetert de duidelijkheid en trefwoorddekking.','%1$d chars, %2$d words — good title.'=>'%1$d tekens, %2$d woorden — goede titel.','Using LF AI meta description.'=>'Gebruik van LF AI meta-beschrijving.','No LF meta description set — using excerpt/content.'=>'Geen LF-meta-beschrijving ingesteld — gebruik excerpt/inhoud.','No meta description found. Generate one via the AI meta description feature.'=>'Geen meta-beschrijving gevonden. Genereer er een via de AI-meta-beschrijvingsfunctie.','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d tekens — te kort (streef naar %2$d–%3$d). %4$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d tekens — waarschijnlijk afgekapt in SERP\'s (houd onder %2$d). %3$s','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d tekens — goed, licht boven het ideale %2$d maar binnen de geaccepteerde %3$d-tekens bereik. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d tekens — ideale lengte. %2$s','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d woorden — zeer dunne inhoud. Overweeg uit te breiden naar minstens %2$d woorden.','%1$d words — below recommended minimum of %2$d.'=>'%1$d woorden — onder de aanbevolen minimum van %2$d.','%d words.'=>'%d woorden.','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'H2-als-H1 modus ingeschakeld — titel telt als H1-equivalent. (Koptekst-tags konden niet worden gedetecteerd op de gerenderde pagina; controleer of je thema de titel correct weergeeft.)','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Geen H1 gevonden. Gewoonlijk is de posttitel de H1 — controleer of je thema deze uitzendt.','%d H1 tags found — a page should have exactly one H1.'=>'%d H1-tags gevonden — een pagina moet precies één H1 hebben.','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — geen H2, maar %d H3-kopjes gevonden (bijvoorbeeld accordeon/details headers). Structuur is acceptabel.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — korte inhoud (%d alinea(\'s)), subkoppen niet vereist.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — geen H2-kopjes (acceptabel voor dit type inhoud).','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — geen H2 of H3 subkoppen gevonden. H2\'s toevoegen verbetert de structuur.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','No images found in content.'=>'Geen afbeeldingen gevonden in de inhoud.','%1$d of %2$d image(s) missing alt text.'=>'%1$d van %2$d afbeeldingen missen alt-tekst.','%d image(s), all have alt text.'=>'%d afbeelding(en), allemaal met alt-tekst.','No links found. Internal links improve crawlability and user navigation.'=>'Geen links gevonden. Interne links verbeteren crawlbaarheid en gebruikersnavigatie.','No links found.'=>'Geen links gevonden.','%d external link(s), no internal links. Add internal links to related content.'=>'%d externe link(en), geen interne links. Voeg interne links toe naar gerelateerde inhoud.','%d external link(s), no internal links.'=>'%d externe link(en), geen interne links.','%1$d internal, %2$d external.'=>'%1$d intern, %2$d extern.','Post not found.'=>'Bericht niet gevonden.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Geen AI-provider geconfigureerd. Voeg een API-sleutel toe in Instellingen → API-sleutels.','No response from AI provider. Check your API key and try again.'=>'Geen reactie van AI-provider. Controleer je API-sleutel en probeer opnieuw.','AI returned an unexpected response format. Please try again.'=>'AI gaf een onverwacht antwoordformaat. Probeer het opnieuw.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge genereert een speciale XML-sitemap op /lf-sitemap.xml die taal-variatielinks toevoegt voor al je vertaalde inhoud. Deze sitemap vult de WordPress-kern sitemap en elke SEO-plugin sitemap aan — vervangt ze niet.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'De WordPress-kern sitemap vermeldt alle URL\'s van je inhoud. De LF sitemap vertelt zoekmachines hoe taalversies zich tot elkaar verhouden via xhtml:link hreflang-varianten. Dien beide in bij Google Search Console voor volledige dekking.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s is actief en genereert zijn eigen sitemap. Die sitemap is gescheiden van die van LF. Beide moeten worden ingediend bij Google Search Console: de SEO-plugin sitemap bevat je inhoud; de LF sitemap voegt de meertalige alternatieve links toe. De LF sitemap wordt automatisch aangekondigd in robots.txt.','Sitemap settings saved.'=>'Sitemap-instellingen opgeslagen.','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Sitemap-cache geleegd. Het wordt opnieuw gegenereerd bij het volgende bezoek aan de sitemap-URL.','Sitemap output'=>'Sitemap-uitvoer','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Genereer de meertalige sitemap op /lf-sitemap.xml','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Wanneer ingeschakeld, wordt de sitemap-URL automatisch aangekondigd in robots.txt en wordt de cache vernieuwd wanneer vertaalde inhoud wordt opgeslagen.','Sitemap URL'=>'Sitemap-URL','Submit this URL to Google Search Console alongside your main sitemap.'=>'Dien deze URL samen met je hoofdsitemap in bij Google Search Console.','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Nog niet gegenereerd. De sitemap wordt gebouwd bij het eerste bezoek aan de sitemap-URL en gecached voor 24 uur.','✓ Active — %d URL entry with language alternates'=>'✓ Actief — %d URL-vermelding met taalalternatieven' . "\0" . '✓ Actief — %d URL-vermeldingen met taalalternatieven','No translated content found. The sitemap will populate once posts have been translated.'=>'Geen vertaalde inhoud gevonden. De sitemap wordt gevuld zodra berichten vertaald zijn.','Last generated: %s'=>'Laatst gegenereerd: %s','Save Sitemap Settings'=>'Opslaan Sitemap-instellingen','Flush Sitemap Cache'=>'Sitemap-cache legen','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Forceert dat de sitemap bij de volgende aanvraag wordt hergenereerd. Gebruik na bulk-import of handmatige bewerking van vertaalrelaties.','IndexNow'=>'IndexNow','IndexNow is an open protocol supported by Bing, Yandex, and other search engines. When a translated post is published or updated, Lingua Forge automatically notifies all participating engines in a single push — no polling, no waiting for the next robots.txt crawl.'=>'IndexNow is een open protocol dat wordt ondersteund door Bing, Yandex en andere zoekmachines. Wanneer een vertaald bericht wordt gepubliceerd of bijgewerkt, informeert Lingua Forge automatisch alle deelnemende engines in één push — geen polling, geen wachten op de volgende robots.txt-crawl.','IndexNow replaces the deprecated Bing and Yandex sitemap-ping endpoints. Google discovers sitemaps via the robots.txt Sitemap: directive as before.'=>'IndexNow vervangt de verouderde Bing- en Yandex-sitemap-ping endpoints. Google ontdekt sitemaps via de robots.txt Sitemap: directive zoals voorheen.','✓ All URLs submitted to IndexNow successfully.'=>'✓ Alle URL\'s succesvol ingediend bij IndexNow.','No translated URLs found to submit. Publish some translated posts first.'=>'Geen vertaalde URL\'s gevonden om in te dienen. Publiceer eerst enkele vertaalde berichten.','✗ IndexNow submission failed. Check that the key file is publicly reachable (see below) and try again.'=>'✗ IndexNow-inzending mislukt. Controleer of het sleuteldossier publiek bereikbaar is (zie hieronder) en probeer het opnieuw.','Verification key'=>'Verificatiesleutel','Key file served automatically at: %s'=>'Sleuteldossier automatisch beschikbaar op: %s','Key could not be generated. Check that the site has write access to WordPress options.'=>'Sleutel kon niet worden gegenereerd. Controleer of de site schrijfrechten heeft op WordPress-opties.','Key file status'=>'Status sleuteldossier','✓ Key file is publicly reachable.'=>'✓ Sleuteldossier is publiek bereikbaar.','✗ Key file is not reachable.'=>'✗ Sleuteldossier is niet bereikbaar.','IndexNow engines verify the key file before accepting submissions. If the file is not reachable, submissions will be rejected with a 403 error.'=>'IndexNow-engines verifiëren het sleuteldossier voordat ze inzendingen accepteren. Als het bestand niet bereikbaar is, worden inzendingen geweigerd met een 403-fout.','Common causes: full-page caching (clear it), a security plugin blocking .txt files, or a custom Nginx/Apache rule. The file is served by LF on every request — no physical file is written to disk.'=>'Veelvoorkomende oorzaken: volledige pagina caching (verwijder het), een beveiligingsplugin die .txt-bestanden blokkeert, of een aangepaste Nginx/Apache-regel. Het bestand wordt door LF bij elke aanvraag geserveerd — er wordt geen fysiek bestand op de schijf geschreven.','Submit all URLs'=>'Dien alle URL\'s in','Submit all URLs via IndexNow'=>'Dien alle URL\'s in via IndexNow','Pushes every published, LF-managed URL to IndexNow in one batch. Automatic submission already runs on every publish/update — use this only after a bulk import or when setting up IndexNow for the first time.'=>'Stuurt elke gepubliceerde, LF-beheerde URL in één batch naar IndexNow. Automatische inzending wordt al uitgevoerd bij elke publicatie/bijwerking — gebruik dit alleen na een bulkimport of bij het instellen van IndexNow voor de eerste keer.','Google does not participate in IndexNow. It discovers sitemaps via the robots.txt Sitemap: directive — which LF has already configured. Use Google Search Console to monitor indexing coverage.'=>'Google neemt niet deel aan IndexNow. Het ontdekt sitemaps via de robots.txt Sitemap: richtlijn — die LF al heeft geconfigureerd. Gebruik Google Search Console om de indexeringsdekking te controleren.','Open Search Console →'=>'Open Search Console →','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt bijgewerkt met Sitemap-richtlijn.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Fysiek robots.txt gevonden. LF\'s Sitemap-richtlijn is aanwezig.','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Er bestaat een fysiek robots.txt-bestand op de site root. WordPress\'s virtuele robots.txt — en LF\'s Sitemap: filter — worden omzeild. De LF sitemap wordt niet aangekondigd aan zoekmachines.','Add Sitemap directive to robots.txt'=>'Voeg Sitemap-richtlijn toe aan robots.txt','Appends the following line to your existing robots.txt: %s'=>'Voegt de volgende regel toe aan je bestaande robots.txt: %s','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS is ingesteld.','Add the following line to your robots.txt manually:'=>'Voeg de volgende regel handmatig toe aan je robots.txt:','View current robots.txt'=>'Bekijk huidig robots.txt','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Geen fysiek robots.txt-bestand gevonden. WordPress genereert het virtueel en LF\'s Sitemap-directive is automatisch inbegrepen.','The following directive is active in your virtual robots.txt:'=>'De volgende richtlijn is actief in je virtuele robots.txt:','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Bestandswijzigingen zijn uitgeschakeld (DISALLOW_FILE_MODS).','Could not write to robots.txt. Check file permissions.'=>'Kon niet schrijven naar robots.txt. Controleer de bestandsrechten.','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge breidt de WordPress Core Social Icons-blok uit met dynamische deel-URL\'s. Stel de link van een pictogram in op een "share:"-waarde en LF herschrijft deze naar de juiste deel-URL of JavaScript-actie bij het renderen — geen aangepaste code of third-party plugin nodig.','Social Share settings saved.'=>'Social Share-instellingen opgeslagen.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'De lf-social-share mu-plugin is actief. Lingua Forge\'s ingebouwde Social Share is inactief — de mu-plugin regelt het herschrijven van share-URL\'s en de JS-acties.','Social Share'=>'Social Share','Enable Social Share URL rewriting for Social Icons blocks'=>'Schakel URL-herziening voor Social Share in voor Social Icons-blokken','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Uitgeschakeld omdat de lf-social-share mu-plugin deze functie al biedt.','Save Social Share Settings'=>'Opslaan Sociale Deel-instellingen','How to use'=>'Hoe te gebruiken','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Voeg in de blokeditor een Social Icons-blok toe. Voor elk pictogram open je de link-instellingen en voer je een van de "share:"-waarden hieronder in als URL. Op de frontend vervangt LF dit door de juiste deel-URL voor de huidige pagina.','External share services'=>'Externe deelservices','URL to enter'=>'URL om in te voeren','Action'=>'Actie','Share on Facebook'=>'Delen op Facebook','Post on X / Twitter'=>'Bericht op X / Twitter','Share on LinkedIn'=>'Delen op LinkedIn','Send via WhatsApp'=>'Verstuur via WhatsApp','Send via Telegram'=>'Verstuur via Telegram','Submit to Reddit'=>'Dien in bij Reddit','Pin on Pinterest'=>'Pin op Pinterest','Share on Mastodon'=>'Delen op Mastodon','Share via email (mailto:)'=>'Delen via e-mail (mailto:)','JavaScript-powered actions'=>'JavaScript-gestuurde acties','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Kopieer de huidige URL naar het klembord. Toont een "Link gekopieerd"-melding bij succes.','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Open de native Web Share-sheet van de browser (iOS, Android, sommige desktops). Valt terug op kopiëren naar klembord als niet ondersteund.','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Gebruik native delen wanneer beschikbaar; val terug op kopiëren naar klembord. Aanbevolen standaard voor "Delen" knoppen.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'De share-URL weerspiegelt altijd de huidige pagina — geen handmatige URL-invoer nodig. De linguaforge_social_share_url filter laat je de opgeloste URL voor elke service overschrijven.','Configuration issue: WP site language has no content on this site'=>'Configuratieprobleem: WP-sitetaal heeft geen inhoud op deze site','The WordPress site language (%1$s) maps to the language code "%2$s", but no posts on this site are tagged _lf_lang=%2$s. This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'De WordPress-sitetaal (%1$s) wordt toegewezen aan de taalcode "%2$s", maar geen berichten op deze site zijn getagd met _lf_lang=%2$s. Dit veroorzaakt dat WooCommerce-productquery\'s nul resultaten retourneren, productafbeeldingen mislukken en alle query\'s voor taalgefiltreerde inhoud breken.','Fix: go to'=>'Oplossing: ga naar','Settings → General → Site Language'=>'Instellingen → Algemeen → Site Taal','and set it to one of your actual content languages (e.g. %s).'=>'en stel het in op een van uw werkelijke inhoudsalen (bijv. %s).','Environment'=>'Omgeving','Lingua Forge version'=>'Lingua Forge-versie','WordPress version'=>'WordPress-versie','PHP version'=>'PHP-versie','Active theme'=>'Actief thema','(FSE / block theme)'=>'(FSE / blokthema)','(classic theme)'=>'(klassiek thema)','URL structure'=>'URL-structuur','Subdomain (de.example.com)'=>'Subdomein (de.voorbeeld.com)','Path prefix (/de/)'=>'Padvoorvoegsel (/de/)','WP instance language'=>'WP-instantie taal','not a content language — see notice above'=>'geen inhoudstaal — zie bovenstaande melding','Primary content language'=>'Primaire inhoudstaal','Active languages'=>'Actieve talen','PHP max_execution_time'=>'PHP max_execution_time','No PHP limit'=>'Geen PHP-limiet','(server/FPM timeout still applies)'=>'(server/FPM time-out geldt nog steeds)','AI translation and batch analysis may time out. Recommend 120s or more.'=>'AI-vertaling en batchanalyse kunnen time-out krijgen. Aanbevolen 120s of meer.','PHP memory_limit'=>'PHP memory_limit','AI Configuration'=>'AI-configuratie','(active)'=>'(actief)','Configured'=>'Geconfigureerd','No key'=>'Geen sleutel','— AI features are disabled.'=>'— AI-functies zijn uitgeschakeld.','Add key →'=>'Voeg sleutel toe →','Light model'=>'Lichtmodel','Quality model'=>'Kwaliteitsmodel','Active preset'=>'Actieve preset','Daily quota'=>'Dagelijkse quota','Unlimited'=>'Onbeperkt','requests / day'=>'verzoeken / dag','Permalink Structure'=>'Permalinkstructuur','Permalink structure is compatible with Lingua Forge path routing.'=>'Permalinkstructuur is compatibel met Lingua Forge padroutering.','Plain permalinks are not supported.'=>'Eenvoudige permalinks worden niet ondersteund.','Path routing requires a post-name based permalink structure. Change it in'=>'Padroutering vereist een permalinkstructuur op basis van berichtnaam. Wijzig dit in','Settings → Permalinks'=>'Instellingen → Permalinks','Numeric permalink structure is not supported.'=>'Numerieke permalinkstructuur wordt niet ondersteund.','Switch to a post-name based structure in'=>'Schakel over naar een structuur op basis van berichtnaam in','SEO Plugins'=>'SEO-plugins','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'Geen detectie van SEO-plugins van derden. Lingua Forge behandelt alle meertalige SEO-uitvoer.','Active: %s.'=>'Actief: %s.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Zie Instellingen → SEO → Compatibiliteit voor de volledige tabel met gedrag per functie.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce is niet actief.','Shop'=>'Winkel','Cart'=>'Winkelwagen','Checkout'=>'Afrekenen','My Account'=>'Mijn account','WooCommerce version'=>'WooCommerce-versie','Order storage'=>'Order opslag','High-Performance Order Storage (HPOS)'=>'High-Performance Order Storage (HPOS)','Custom tables — LF post-meta filters do not affect orders.'=>'Aangepaste tabellen — LF post-meta filters beïnvloeden geen bestellingen.','Shared / compatibility mode'=>'Gedeelde / compatibiliteitsmodus','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT gesynchroniseerd — overgangsperiode; LF post-meta filters worden toegepast op kopie van CPT.','Legacy post-based (CPT)'=>'Legacy berichtgebaseerd (CPT)','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'Bestellingen in wp_posts — zorg dat shop_order niet wordt meegenomen in LF-routing.','WcPageBridge active'=>'WcPageBridge actief','Yes'=>'Ja','No — WooCommerce integration class not loaded'=>'Geen — WooCommerce-integratieklasse niet geladen','WooCommerce page translations'=>'WooCommerce-paginatranslaties','No secondary languages configured.'=>'Geen secundaire talen geconfigureerd.','Active Plugins'=>'Actieve Plugins','No active plugins detected.'=>'Geen actieve plugins gedetecteerd.','Version'=>'Versie','_lf_lang Coverage'=>'_lf_lang Dekking','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'Berichten zonder _lf_lang zijn onzichtbaar voor elke Lingua Forge-taalfilter. Dit kan gebeuren wanneer inhoud wordt geïmporteerd of gemaakt voordat de plugin werd geactiveerd.','All published posts have a _lf_lang value. No gaps detected.'=>'Alle gepubliceerde berichten hebben een _lf_lang waarde. Geen gaten gedetecteerd.','Missing'=>'Ontbrekend','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Sluit dit berichttype uit van taalkoppeling — de berichten verschijnen hier niet meer of ontvangen _lf_lang. Dit kan niet automatisch worden teruggedraaid.','Exclude from routing'=>'Uitsluiten van routing','excluded from routing'=>'uitgesloten van routing','Destructive action — read before proceeding'=>'Verwoestende actie — lees voordat je doorgaat','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Repareer tags voor elke routable post die hierboven wordt vermeld met _lf_lang = %s. Posts in routing-uitgesloten posttypes worden niet aangepast. Voer dit alleen uit na het importeren van inhoud of bij eerste activatie — gebruik het niet als bulk-taaltoewijzingstool.','Repair — assign _lf_lang = %s to all routable posts above'=>'Repareer — ken _lf_lang = %s toe aan alle routable posts hierboven','Rewrite Rules'=>'Herschrijfregels','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'LF-eigendom entries momenteel geregistreerd in $wp_rewrite->extra_rules_top. Handig voor het diagnosticeren van 404-fouten of routeringsconflicten. Kopieer deze bij het indienen van een bugrapport.','%d rule registered'=>'%d regel geregistreerd' . "\0" . '%d regels geregistreerd','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'Geen LF herschrijfregels gevonden. Leeg de permalinks als dit onverwacht is.','Debug Info'=>'Debug-info','Copy and paste into a GitHub issue or support request.'=>'Kopieer en plak in een GitHub-issue of supportverzoek.','Copy system info'=>'Systeeminfo kopiëren','Copied!'=>'Gekopieerd!','Repairing…'=>'Repareren…','Repair failed.'=>'Reparatie mislukt.','Network error.'=>'Netwerkfout.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'Sluit dit berichttype uit van taalkoppeling? De berichten verschijnen niet meer in deze lijst of ontvangen _lf_lang. Je kunt dit terugdraaien in Instellingen → Router → Query Filter Uitsluitingen.','Excluding…'=>'Wordt uitgesloten…','Failed to save exclusion.'=>'Het opslaan van uitsluiting is mislukt.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d bericht getagd met _lf_lang = %2$s.' . "\0" . '%1$d berichten getagd met _lf_lang = %2$s.','Uninstall Behaviour'=>'Oninstallatiegedrag','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Regelt wat er gebeurt wanneer een beheerder de plugin verwijdert via Plugins → Geïnstalleerde plugins → Verwijderen. Plugin-instellingen en AI-caches worden altijd verwijderd. Taaltoewijzingen en vertaalrelaties worden standaard bewaard zodat een per ongeluk deïnstallatie of herinstallatie kan hervatten waar het was gebleven.','Uninstall setting saved.'=>'Deïnstallatie-instelling opgeslagen.','Delete content data on uninstall'=>'Verwijder inhoudsgegevens bij deïnstallatie','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Verwijder ook taaltoewijzingen, vertaalrelaties, meta-beschrijvingen, woordenlijst en Vertaalgeheugen wanneer de plugin wordt verwijderd.','Warning:'=>'Waarschuwing:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Als dit is aangevinkt, wordt bij het verwijderen van de plugin alle taaltoewijzingen, vertaalrelaties, meta-beschrijvingen, paginapresets, het AI-woordenboek en Vertaalgeheugen permanent verwijderd voor elke bericht op deze site. Dit kan niet worden teruggedraaid. Laat het uitgevinkt tenzij je volledig meertalige ondersteuning van de site verwijdert.','Save Uninstall Setting'=>'Instelling voor deïnstallatie opslaan','Today'=>'Vandaag','Last 7 days'=>'Afgelopen 7 dagen','Last 30 days'=>'Afgelopen 30 dagen','All time'=>'Alles','AI Usage'=>'AI-gebruik','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Tokenverbruik wordt samengevoegd per functie, provider en model. Vastgelegd bij elke succesvolle AI-aanroep; Testverbinding-pings worden uitgesloten zodat ze de totalen niet vertekenen.','Check your account, billing, or remaining credits directly on the provider console:'=>'Controleer je account, facturering of resterende credits direct op de provider console:','Anthropic Console'=>'Anthropic Console','OpenAI Platform'=>'OpenAI Platform','Google AI Studio'=>'Google AI Studio','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Nog geen AI-gebruik geregistreerd. Zodra een editor een vertaling uitvoert, een meta-beschrijving genereert of een andere AI-functie gebruikt, verschijnen de totalen hier.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Geen AI-gebruik geregistreerd in het geselecteerde venster (%s). Kies een breder bereik hierboven.','Provider'=>'Provider','Model'=>'Model','Requests'=>'Verzoeken','Input tokens'=>'Invoertokens','Output tokens'=>'Uitvoertokens','Total tokens'=>'Totaal tokens','Total'=>'Totaal','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge voegt WooCommerce-specifieke Open Graph-eigenschappen toe aan productpagina\'s zodat het delen van een product-URL op Facebook, Pinterest en soortgelijke platforms het juiste producttype, prijs en beschikbaarheid toont.','WooCommerce SEO settings saved.'=>'WooCommerce SEO-instellingen opgeslagen.','Product Open Graph'=>'Product Open Graph','Add WooCommerce product tags to Open Graph output'=>'Voeg WooCommerce-producttags toe aan Open Graph-uitvoer','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Wanneer ingeschakeld, geeft Lingua Forge de volgende extra meta-tags weer op productpagina\'s: og:type=product, og:price:amount, og:price:currency, og:availability, en hun product: namespace-equivalenten gebruikt door Facebook Catalog.','Tags emitted'=>'Uitgezonden tags','Tag'=>'Tag','Value source'=>'Bron van waarde','"product" (replaces "article")'=>'"product" (vervangt "artikel")','WooCommerce product price'=>'WooCommerce productprijs','WooCommerce store currency'=>'WooCommerce winkelvaluta','instock / oos / pending from WC stock status'=>'in voorraad / niet op voorraad / in afwachting van WC-voorraadstatus','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Prijs en beschikbaarheid weerspiegelen altijd het product in de brontaal (gedeeld voorraadmodel). Tags worden alleen weergegeven wanneer LF\'s Open Graph-module is ingesteld op "Volledig" of "Auto" modus zonder conflicterende SEO-plugin.','Save WooCommerce SEO Settings'=>'Opslaan WooCommerce SEO-instellingen','AI Provider'=>'AI-provider','AI Usage & Cache'=>'AI-gebruik & cache','API Keys'=>'API-sleutels','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Sleutels worden versleuteld met AES-256-CBC voordat ze in de WordPress-database worden opgeslagen. Het encryptiegeheim wordt afgeleid van je WordPress-authentificatiesalts (wp-config.php), zodat platte tekst-sleutels nooit de database raken.','API credentials are managed by WordPress in %s. No key is stored by Lingua Forge.'=>'API-inloggegevens worden beheerd door WordPress in %s. Geen sleutel wordt opgeslagen door Lingua Forge.','Settings → Connectors'=>'Instellingen → Connectors','API Key'=>'API-sleutel','Paste your API key…'=>'Plak je API-sleutel…','✓ Configured'=>'✓ Geconfigureerd','✗ Not configured'=>'✗ Niet geconfigureerd','Test connection'=>'Testverbinding','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Laat leeg om de bestaande sleutel te behouden. Voer een nieuwe waarde in om deze te vervangen.','Remove stored key'=>'Verwijder opgeslagen sleutel','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Deze sleutel wordt momenteel geleverd door een server %s en kan hier niet worden verwijderd. Voer een nieuwe sleutel hierboven in om deze te overschrijven met een databasewaarde.','environment variable'=>'omgevingsvariabele','PHP constant'=>'PHP-constante','Alternative (server-side):'=>'Alternatief (serverzijde):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Je kunt sleutels ook definiëren als constanten of omgevingsvariabelen (bijvoorbeeld in wp-config.php). Die bronnen worden automatisch gebruikt als fallback wanneer er geen database-sleutel is opgeslagen.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Om een aangepaste encryptiegeheim te gebruiken (in plaats van de afgeleide wp_salt-waarde), voeg dit toe aan wp-config.php:','Unknown provider.'=>'Onbekende provider.','No API key configured for this provider.'=>'Geen API-sleutel geconfigureerd voor deze provider.','Could not instantiate the provider.'=>'Kon de provider niet initialiseren.','Provider returned no response. Check the WordPress error log for details.'=>'De provider gaf geen reactie. Controleer het WordPress-foutlog voor details.','Enter a model identifier to test.'=>'Voer een model-identifier in om te testen.','No published post or page found to test with — publish some content first, or try Quick Translate directly.'=>'Geen gepubliceerd bericht of pagina gevonden om mee te testen — publiceer eerst wat content, of probeer Direct vertalen rechtstreeks.','(untitled)'=>'(zonder titel)','Prompt template not found.'=>'Promptsjabloon niet gevonden.','Translation failed. Please try again.'=>'Vertaling mislukt. Probeer het opnieuw.','The sample post has no visible text content to translate.'=>'Het voorbeeldbericht bevat geen zichtbare tekstinhoud om te vertalen.','Chunk prompt template not found.'=>'Sjabloon voor chunk-prompt niet gevonden.','Model returned no response. Check the WordPress error log for details.'=>'Model heeft geen antwoord gegeven. Controleer het WordPress-foutlogboek voor details.','Behavior'=>'Gedrag','Block Editor'=>'Block Editor','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge beperkt standaard twee Gutenberg-functies om het redactionele gedrag consistent te houden over talen. Meld je hier aan als je volledige Gutenberg / FSE-mogelijkheden nodig hebt.','Block locking'=>'Blokvergrendeling','Allow editors to lock individual blocks'=>'Sta redacteuren toe om individuele blokken te vergrendelen','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Heractiveert Gutenberg\'s canLockBlocks. Handig voor redactionele sjablonen die voorkomen dat bijdragers bepaalde blokken verplaatsen of verwijderen.','Template mode'=>'Sjabloonmodus','Allow Gutenberg template-editing mode on post screens'=>'Sta Gutenberg sjabloonbewerkingsmodus toe op berichtenschermen','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Heractiveert supportsTemplateMode. Kern voor workflows met volledige site-bewerking waar op berichtniveau sjabloonoverschrijvingen opzettelijk zijn.','Compliance Preset'=>'Nalevingspreset','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Strikte-preservatiemodus voor juridische, regelgevende, medische of technische inhoud. Wanneer ingeschakeld, gebruikt elke AI-functie een lage bemonsteringstemperatuur en voegt de onderstaand addendum toe aan de systeemprompt — terminologie, artikelnummers, eenheden, merknamen en regelgeving worden letterlijk behouden in plaats van te worden geparafraseerd.','Global AI preset'=>'Globale AI-preset','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, per functie','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Stelt het standaard AI-gedrag in voor alle functies site-breed. Individuele berichten kunnen dit overschrijven voor Vertaling en Inhoudsgeneratie via de Lingua Forge meta box.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standaard gebruikt de eigen afgestelde temperatuur van elke functie: Vertaling T=0.2 (nauwkeurig), Snelle Vertaling T=0.4, Inhoudsgenerator T=0.6 (creatief). De andere presets passen een enkele vaste temperatuur toe op alle functies.','Technical / Scientific instructions'=>'Technische / Wetenschappelijke instructies','Legal / Compliance instructions'=>'Juridische / Nalevingsinstructies','Creative / Marketing instructions'=>'Creatieve / Marketing instructies','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Laat leeg om de ingebouwde standaard te gebruiken. Het wissen van een opgeslagen overschrijving herstelt de standaard bij de volgende opslag.','View built-in default'=>'Bekijk ingebouwde standaard','Automatic Translation Backfill'=>'Automatische vulling van vertalingen','Periodically scans for posts missing a translation in an active language and queues an AI translation for each gap found — the same recovery you can already trigger by hand via "Translate missing" or the WP-CLI missing_translations/fill_translations commands, run automatically once an hour instead.'=>'Scant periodiek naar berichten zonder vertaling in een actieve taal en plaatst een AI-vertaling voor elke gevonden lacune in de wachtrij — hetzelfde herstel dat u al kunt activeren via "Ontbrekende berichten vertalen" of de WP-CLI-commando\'s missing_translations/fill_translations, maar dan automatisch elke uur.','Automatic backfill'=>'Automatische vulling','Automatically translate posts missing a language version'=>'Vertaal automatisch berichten die in een bepaalde taal ontbreken','Off by default. This feature makes AI provider requests — and spends the associated API cost — automatically and in the background, with no per-request confirmation, for every published post found without a translation in an active language. Turn this on only if you want every content gap translated unattended; otherwise use "Translate missing" or the WP-CLI commands to translate on your own schedule.'=>'Standaard uitgeschakeld. Deze functie doet API-verzoeken bij AI-providers — en geeft de bijbehorende API-kosten uit — automatisch en op de achtergrond, zonder bevestiging per verzoek, voor elk gepubliceerd bericht zonder vertaling in een actieve taal. Schakel dit alleen in als u wilt dat elke inhoudslacune zonder toezicht wordt vertaald; anders gebruikt u "Ontbrekende berichten vertalen" of de WP-CLI-commando\'s om op uw eigen schema te vertalen.','WooCommerce products and variations are never included, regardless of this setting. An integration can also block specific post types via the linguaforge_cpt_create_allowed filter.'=>'WooCommerce-producten en variaties worden nooit opgenomen, ongeacht deze instelling. Een integratie kan ook bepaalde berichttypen blokkeren via het linguaforge_cpt_create_allowed filter.','The "Sync" button in the post list Lang column retranslates a post out into every other language, including the primary/source post when it\'s run from a translation. That back-translation direction is restricted by default for every post type. (WooCommerce products and variations have their own separate setting below — this one does not affect them.)'=>'De knop "Synchroniseren" in de kolom Lang van de berichtenlijst vertaalt een bericht opnieuw naar elke andere taal, inclusief de primaire/source-taal wanneer deze wordt uitgevoerd vanuit een vertaling. Die back-translatierichting is standaard beperkt voor elk berichttype. (WooCommerce-producten en variaties hebben hun eigen aparte instelling hieronder — deze is niet van toepassing op hen.)','Secondary-language Sync'=>'Synchroniseren in secundaire taal','Allow "Sync" on a translated post to overwrite the primary post'=>'Sta "Synchroniseren" op een vertaald bericht toe om het primaire bericht te overschrijven','Off by default: clicking "Sync" on a translation is blocked from overwriting the primary post. Syncing FROM the primary post to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Standaard uitgeschakeld: klikken op "Synchroniseren" voor een vertaling wordt geblokkeerd zodat het primaire bericht niet wordt overschreven. Synchroniseren VANUIT het primaire bericht naar elke vertaling is altijd toegestaan, ongeacht deze instelling. Schakel dit alleen in als u opzettelijk wilt dat een vertaling de nieuwe broncontent kan worden.','The primary-language product is WooCommerce\'s operational source of truth for price, SKU, and stock, which are always served from it regardless of which language a shopper is viewing. This is a separate, independent setting from the general "Sync" restriction above — enabling one does not enable the other.'=>'Het product in de primaire taal is de operationele bron voor WooCommerce voor prijs, SKU en voorraad, die altijd vanaf hier worden bediend, ongeacht welke taal een koper bekijkt. Dit is een afzonderlijke, onafhankelijke instelling van de algemene "Synchroniseren"-beperking hierboven — het inschakelen van de ene schaelt de andere niet in.','Allow "Sync" on a translated product to overwrite the primary product'=>'Sta "Synchroniseren" op een vertaald product toe om het primaire product te overschrijven','Off by default: clicking "Sync" on a translated WooCommerce product is blocked, since it would back-translate onto the primary product\'s title, description, and excerpt. Syncing FROM the primary product to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Standaard uitgeschakeld: klikken op "Synchroniseren" voor een vertaald WooCommerce-product wordt geblokkeerd, omdat het terug zou vertalen naar de titel, beschrijving en samenvatting van het primaire product. Synchroniseren VANUIT het primaire product naar elke vertaling is altijd toegestaan, ongeacht deze instelling. Schakel dit alleen in als u opzettelijk wilt dat een vertaling de nieuwe broncontent kan worden.','General'=>'Algemeen','Light'=>'Licht','Meta Description, Excerpt Generator, quick translate'=>'Meta Beschrijving, Uittreksel Generator, snelle vertaling','Quality'=>'Kwaliteit','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Volledige pagina Vertaling, Content Generator (middelgrote modellen zijn volledig voldoende)','Active Provider'=>'Actieve provider','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Momenteel geërfd van de %s-constante. Het selecteren van een waarde hier overschrijft deze.','WordPress AI Client — requirements:'=>'WordPress AI Client — vereisten:','Full-page translation uses JSON-schema-constrained output. This requires a connector plugin to be installed and active (not just an API key saved in Settings → Connectors). If translation fails, check the PHP error log for the specific error, or switch to a built-in provider.'=>'Volledige pagina vertaling gebruikt JSON-schema-beperkte output. Dit vereist dat een connector-plugin geïnstalleerd en actief is (niet alleen een API-sleutel opgeslagen in Instellingen → Connectors). Als vertaling mislukt, controleer dan het PHP-foutlog op de specifieke fout, of schakel over naar een ingebouwde provider.','Manage your account, review usage, or top up credits:'=>'Beheer je account, bekijk gebruik of vul credits bij:','WordPress Connectors'=>'WordPress-connectoren','Models'=>'Modellen','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Functies zijn gegroepeerd in twee niveaus. Voer de exacte modelidentificatie voor elk niveau en provider in. Laat een veld leeg om de ingebouwde standaard te gebruiken (weergegeven als placeholder). Alleen de modellen van de actieve provider worden tijdens runtime aangeroepen — configureer de anderen vooraf als je wilt wisselen.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Begin met typen in elk veld om modelvoorstellen te zien, of gebruik de referentietabel hieronder. Licht- en middenklasse kwaliteitsmodellen (Haiku, GPT-4o mini, Gemini Flash) zijn volledig geschikt voor vertaling en inhoudsgeneratie — vlaggenschip "max"-modellen brengen kosten met zich mee met minimale kwaliteitswinst voor gestructureerde tekst.','active'=>'actief','Model selection is managed by WordPress in %s — no model identifier is stored by Lingua Forge for this provider.'=>'Modelkeuze wordt beheerd door WordPress in %s — geen modelidentificator wordt opgeslagen door Lingua Forge voor deze provider.','overridden'=>'overschreven','Translates a short sample of your most recent published post with this exact model — a real, billed API call.'=>'Vertaalt een kort voorbeeld van uw meest recent gepubliceerde bericht met dit exacte model — een echt, gefactureerd API-aanroep.','Test model'=>'Testmodel','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: om een model terug te zetten naar de ingebouwde standaard, wis het veld en sla op.','Available models reference'=>'Referentie beschikbare modellen','Model ID'=>'Model ID','Name'=>'Naam','Tier'=>'Niveau','Notes'=>'Notities','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Deze catalogus wordt bijgewerkt bij elke Lingua Forge-release. Het testen van een verbinding in het tabblad API-sleutels haalt ook de live model-lijst op van de provider en vernieuwt de suggesties hierboven.','Glossary'=>'Woordenlijst','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Gebruikersbeheer van terminologietabel per taalpaar. Items worden toegevoegd aan de vertaalprompt zodat de AI voorkeurstermen consequent gebruikt — essentieel voor domeinspecifieke vocabulaire ("kWp", "PPA", "interconnection point"), merknamen die niet vertaald mogen worden, en gestandaardiseerde regelgevingsteksten. Beide taalvelden zijn optioneel: laat "Bron taal" leeg om de invoer toe te passen ongeacht vanuit welke taal je vertaalt; laat "Doeltaal" leeg om het op alle doeltalen tegelijk toe te passen.','Glossary entry added.'=>'Woordenlijstitem toegevoegd.','Glossary entry removed.'=>'Woordenlijstitem verwijderd.','Could not add entry: source term and target term are required.'=>'Kan item niet toevoegen: bronterm en doeltaal zijn verplicht.','Could not save the glossary entry.'=>'Kan het woordenlijstitem niet opslaan.','Source language'=>'Bron taal','— Any —'=>'— Any —','Target language'=>'Doeltaal','— Any target —'=>'— Elke doeltaal —','Filter'=>'Filter','Reset'=>'Reset','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Geen woordenlijstitems die overeenkomen met het huidige filter. Wis het filter om alle items te zien, of voeg hieronder een nieuw item toe.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Nog geen woordenlijstitems. Voeg er hieronder een toe om terminologie in vertalingen af te dwingen.','Source term'=>'Bronterm','Target term'=>'Doeltaal','Source lang'=>'Bron taal','Target lang'=>'Doeltaal','any'=>'any','Delete this glossary entry?'=>'Wil je dit woordenlijstitem verwijderen?','Add new entry'=>'Nieuw item toevoegen','The phrase as it appears in the source text.'=>'De uitdrukking zoals deze in de brontekst voorkomt.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Hoe het in de vertaling moet verschijnen. Typ dezelfde waarde als de bronterm om de AI te instrueren deze woord voor woord te behouden.','— Any source language —'=>'— Elke bron taal —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Laat leeg voor merknamen en taal-onafhankelijke termen die ongeacht de taal waarin we vertalen gehandhaafd moeten worden.','— Any target language —'=>'— Elke doeltaal —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Laat leeg om deze invoer op alle doeltalen toe te passen — ideaal voor merknamen, afkortingen en termen die in elke vertaling woord voor woord behouden moeten blijven.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Optioneel context voor editors (bijv. "ASIC = Application-Specific Integrated Circuit; in technische contexten in het Engels behouden").','Add entry'=>'Item toevoegen','Limits'=>'Limieten','Authors and above (edit_published_posts)'=>'Auteurs en hoger (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Bijdragers en hoger — standaard (edit_posts)','Editors and above (edit_others_posts)'=>'Editors en hoger (edit_others_posts)','Administrators only (manage_options)'=>'Alleen beheerders (manage_options)','AI Limits & Security'=>'AI Limieten & Beveiliging','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Beperk hoeveel AI-gebruik de site kan genereren en beperk welke gebruikersrollen betaalde AI-aanroepen kunnen triggeren. Staat boven de per-gebruiker limiet (30 verzoeken / minuut, hardcoded) die al bescherming biedt tegen runaway loops van één gebruiker.','Daily request limit'=>'Dagelijkse verzoeklimiet','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Site-brede plafond op AI-verzoeken per UTC-dag (telt zowel Toolbar-vertalingen als blokwijzigingen). Teller wordt gereset om middernacht UTC. Zet op 0 om de limiet uit te schakelen.','Minimum role'=>'Minimale rol','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Laagste WordPress-capability die toegestaan is om AI-functies te activeren. Het aanscherpen hiervan op multi-auteur sites voorkomt dat bijdragers of proefaccounts betaalde AI-aanroepen uitvoeren. Overschrijf per functie via de linguaforge_required_capability filter.','Translation Limits'=>'Vertaal Limieten','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Beheer hoeveel inhoud naar de AI wordt gestuurd en hoe groot het antwoord mag zijn. Laat een veld leeg om de ingebouwde standaard te gebruiken (als placeholder weergegeven). Verhoog deze waarden als grote pagina\'s worden afgekapt; verlaag ze om API-kosten te verminderen.','Model tier'=>'Modelniveau','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kwaliteit (standaard — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Licht (snel en kosteneffectief — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Welk modelniveau te gebruiken voor volledige pagina vertaling. Kwaliteit gebruikt het model dat in de Models tabel hierboven is geconfigureerd en wordt aanbevolen voor nauwkeurige, lange vertalingen. Schakel over naar Licht alleen als snelheid of kosten prioriteit heeft en de inhoud kort is.','Max output tokens'=>'Maximaal output tokens','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maximaal aantal tokens dat de AI in één vertaalantwoord mag produceren. Als een vertaling stilletjes wordt afgekapt, verhoog dan deze waarde. Standaard: 16.000.','Max input characters'=>'Maximaal invoer tekens','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maximum aantal tekens van de berichtinhoud die naar de AI wordt doorgestuurd. 0 betekent geen limiet — de volledige inhoud wordt altijd verzonden (aanbevolen). Stel een niet-nul waarde in alleen als je provider een strakke contextvenster heeft. Er wordt een waarschuwing geschreven naar het PHP-foutlog wanneer de inhoud wordt ingekort.','Quick Translation'=>'Snelle Vertaling','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Snelle Vertaling wordt gebruikt voor snippet/fragmentmodus — korte passages vertaald op aanvraag vanuit de werkbalk, editor of blokpopovers. Het gebruikt een aparte, lichtere configuratie dan de volledige pagina vertaling om reacties snel en kosteneffectief te houden.','Light (default — fast and cost-effective)'=>'Licht (standaard — snel en kosteneffectief)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kwaliteit (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'De Light-tier gebruikt het snelle model dat is geconfigureerd in de Models-tabel hierboven (standaard: Haiku / Flash). Schakel over naar Kwaliteit als je dezelfde vertaalkauwiteit nodig hebt als in de volledige pagina modus voor snippets.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maximaal tokens die de AI mag produceren per snelle vertaling. Standaard: 2.000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Maximaal toegestane tekens uit het invoerveld. Standaard: 8.000.','Content Generator'=>'Content Generator','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Regelt het tokenbudget en de invoerlimieten voor de AI Content Generator-functie. Laat velden leeg om de ingebouwde standaardwaarden te gebruiken.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maximaal tokens die de AI mag produceren per generatie. Verhoog dit als volledige artikelen worden afgekapt. Standaard: 8.192.','Max hints characters'=>'Max hints tekens','Maximum characters read from the Hints field. Default: 2 000.'=>'Maximaal gelezen tekens uit het hints-veld. Standaard: 2.000.','Max context characters'=>'Max context tekens','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maximaal aantal tekens van bestaande berichtinhoud dat wordt doorgegeven aan de AI als zaadcontext wanneer geen hints worden gegeven. Standaard: 6.000.','Maintenance'=>'Onderhoud','Router'=>'Router','Primary language saved.'=>'Primaire taal opgeslagen.','Permalink rules flushed successfully.'=>'Permalink-regels succesvol gewist.','Language uninstalled. %d post deleted.'=>'Taal gedeïnstalleerd. %d bericht verwijderd.' . "\0" . 'Taal gedeïnstalleerd. %d berichten verwijderd.','%d locale file removed.'=>'%d locale-bestand verwijderd.' . "\0" . '%d locale-bestanden verwijderd.','%d pattern translation removed.'=>'%d patroonvertaling verwijderd.' . "\0" . '%d patroonvertalingen verwijderd.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d locale-bestand kon niet automatisch worden verwijderd (DISALLOW_FILE_MODS is ingesteld). Verwijder het handmatig via je server of WP-CLI: wp language core uninstall <locale>.' . "\0" . '%d locale-bestanden konden niet automatisch worden verwijderd (DISALLOW_FILE_MODS is ingesteld). Verwijder ze handmatig via je server of WP-CLI: wp language core uninstall <locale>.','Primary Language'=>'Primaire taal','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'De primaire taal wordt altijd op de root van je site bediend — geen URL-prefix in padmodus, geen taal-subdomein in subdomeinmodus. Alle andere talen gebruiken of een /taal/ padprefix (bijvoorbeeld example.com/de/) of een taal-subdomein (bijvoorbeeld de.example.com), afhankelijk van de URL-structuur hieronder.','Primary language'=>'Primaire taal','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Na het wijzigen van de primaire taal, wis de permalinks (sectie hieronder) zodat de URL-routing wordt bijgewerkt.','Path prefix — example.com/de/'=>'Padvoorvoegsel — example.com/de/','Subdomain — de.example.com/'=>'Subdomein — de.voorbeeld.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Subdomeinmodus vereist dat je webserver alle taal-subdomeinen (bijvoorbeeld de.voorbeeld.com) naar deze WordPress-installatie wijst. Na het overschakelen van modi, vernieuw de permalinkregels en wis alle caches. Als je start-URL www bevat (bijvoorbeeld www.voorbeeld.com), gebruik dan de lf_base_domain filter om het bare apex-domein in te stellen zodat subdomeinen correct worden opgebouwd.','Browser language redirect'=>'Browsertaal omleiding','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Verwijs bezoekers door naar hun voorkeurstaal op basis van de Accept-Language header van de browser','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Wanneer ingeschakeld, worden eerste keer bezoekers zonder taalcookie en zonder taalprefix in de URL doorgestuurd naar de dichtstbijzijnde overeenkomende taalversie. De omleiding wordt overgeslagen als de voorkeurstaal van de browser niet onder de actieve routertalen valt. Zodra een bezoeker een taal kiest via de switcher, krijgt de cookie prioriteit en wordt de browserheader genegeerd bij alle toekomstige bezoeken.','Query Filter Exclusions'=>'Uitsluitingen voor Query Filter','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge beperkt secundaire WP_Query-instanties (zijbalk-widgets, sjabloonblokken, plugin-zoekopdrachten) tot de actieve taal door een _lf_lang meta-constraint te injecteren. Berichttypen die hier worden vermeld, worden uitgesloten van die beperking — hun zoekopdrachten worden altijd niet-gefiltred.','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Contact Form 7 (wpcf7_contact_form), Flamingo contacten en inkomende berichten (flamingo_contact, flamingo_inbound), en WordPress taalpakket synchronisatieopslag (wp_sync_storage) worden automatisch uitgesloten. Voeg andere derde partij berichttypen toe waarvan de inhoud niet door de taalfilter moet worden gehaald, één per regel of gescheiden door komma\'s.','Excluded post types'=>'Uitgesloten berichttypen','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Posttype-slugs gescheiden door komma\'s of nieuwe regels. Wijzigingen worden onmiddellijk doorgevoerd bij opslaan — geen permalink-flush nodig.','WooCommerce Integration'=>'WooCommerce-integratie','Controls how Lingua Forge integrates with WooCommerce order processing.'=>'Regelt hoe Lingua Forge integreert met WooCommerce-bestelverwerking.','Order line item source mapping'=>'Orderregel bronmapping','Normalize order line item product IDs to the source-language product at checkout'=>'Normaliseer orderregel product-ID\'s naar het bron-taalproduct bij afrekenen','When enabled (recommended), the product ID stored on each WooCommerce order line item is set to the source-language product. This ensures total_sales counts, WC Analytics revenue rows, and third-party ERP exports reference one product ID per SKU rather than one per language version. Trade-off: "View product" links in order emails and My Account lead to the source-language page. Disable only if a connected system relies on translated product IDs in orders. Use the linguaforge_wc_order_item_source_mapping filter for per-item overrides.'=>'Wanneer ingeschakeld (aanbevolen), wordt de product-ID die op elke WooCommerce-bestelregel staat, ingesteld op het bron-taalproduct. Dit zorgt ervoor dat total_sales tellingen, WC Analytics omzetrijen en derde-partij ERP-exporten naar één product-ID per SKU verwijzen in plaats van één per taalversie. Afweging: "Bekijk product"-links in ordermails en Mijn Account leiden naar de bron-taalpagina. Schakel alleen uit als een verbonden systeem afhankelijk is van vertaalde product-ID\'s in bestellingen. Gebruik de filter linguaforge_wc_order_item_source_mapping voor per-item overrides.','Save Router Settings'=>'Routerinstellingen opslaan','Flush Permalinks'=>'Permalinks verversen','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Hernoopt WordPress herschrijfregels zodat URL-prefixen, taalspecifieke slugs en archiefherschrijvingen allemaal in sync zijn. Nodig na het wijzigen van de primaire taal of het toevoegen van nieuwe taalondersteuning.','Flush Permalink Rules'=>'Permalinkregels verversen','Active Languages'=>'Actieve talen','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Talen die momenteel bekend zijn bij de router (afgeleid van geïnstalleerde WordPress locale-pakketten plus de primaire taal). Installeer extra taalpakketten in het onderstaande gedeelte om meer talen beschikbaar te maken voor routering en vertaling.','%d locale pack installed.'=>'%d locale-pakket geïnstalleerd.' . "\0" . '%d locale-pakketten geïnstalleerd.','Install a Language'=>'Een taal installeren','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Download en installeer een WordPress kern taalpakket rechtstreeks van WordPress.org. Zodra geïnstalleerd, wordt de locale beschikbaar voor URL-routering en de AI-vertalingsworkflow. De lijst met beschikbare talen wordt op aanvraag opgehaald — klik op de knop hieronder om deze te laden.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Taalinstallatie is uitgeschakeld op deze server. De constante DISALLOW_FILE_MODS is ingesteld in wp-config.php. Installeer taalpakketten handmatig via WP-CLI: wp language core install de_DE','Load available languages'=>'Beschikbare talen laden','— select a language —'=>'— kies een taal —','Install'=>'Installeren','Language Setup'=>'Taalinstelling','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Geen secundaire talen geconfigureerd. Installeer een taalpakket hierboven om sjabloonopbouw mogelijk te maken.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Kies een taal om de FSE-sjablonen, sjabloononderdelen en navigatiemenu\'s te beheren.','Recreate All Languages'=>'Alle talen opnieuw aanmaken','Recreate All Languages (Templates Only)'=>'Alle talen opnieuw aanmaken (alleen templates)','Recreate All Languages (Template Parts Only)'=>'Alle talen opnieuw aanmaken (alleen templateonderdelen)','Cancel'=>'Annuleren','Repair Template Metadata'=>'Repareer sjabloonmetadata','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'Repareert de namespace van de Site Editor en de _lf_lang-tag op alle LF-gestoffeerde FSE-sjablonen die in de database zijn opgeslagen. Voer dit eenmaal uit na het bijwerken van een eerdere versie van Lingua Forge — het verplaatst door WooCommerce afgeleide sjablonen van de actieve thema-groep naar de WooCommerce-groep in de Site Editor, en zorgt ervoor dat alle gestoffeerde sjablonen door rapporten kunnen worden gevonden.','Repair template metadata'=>'Repareer sjabloonmetadata','Request failed.'=>'Verzoek mislukt.','Forbidden'=>'Verboden','Danger Zone'=>'Gevaarlijke zone','Uninstall %s'=>'Verwijder %s','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Verwijdert permanent alle sjablonen, sjabloononderdelen, patronen, navigatiemenu\'s, berichten, pagina\'s, aangepaste berichttypen, producten en productvariaties die aan deze taal gekoppeld zijn. Verwijdert ook de WordPress-localebestanden zodat deze taal niet meer in de router verschijnt. Deze actie kan niet ongedaan gemaakt worden.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Deze taal komt overeen met de locale van de WordPress-instantie en kan niet worden verwijderd.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Verwijder %s permanent? Dit zal alle vertaalde inhoud voor deze taal verwijderen en kan niet ongedaan gemaakt worden.','Invalid language code.'=>'Ongeldige taalcodering.','This language is protected and cannot be uninstalled.'=>'Deze taal is beschermd en kan niet worden verwijderd.','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Taalinstallatie is uitgeschakeld op deze server (DISALLOW_FILE_MODS is ingesteld).','Invalid locale code.'=>'Ongeldige locale-code.','Language %s installed successfully.'=>'Taal %s succesvol geïnstalleerd.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Taalpakketinstallatie mislukt. De taal is mogelijk al geïnstalleerd, de locale-code is mogelijk onjuist, of je server blokkeert bestandschrijfbevoegdheden.','Navigations'=>'Navigaties','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Navigatievertaling vereist een actieve AI-provider. Configureer een API-sleutel in het tabblad API-sleutels.','Navigation'=>'Navigatie','Re-translate'=>'Hertaal opnieuw','CPT Block Patterns'=>'CPT-blokpatronen','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Patronen geregistreerd voor aangepaste berichttypen. Gebruik de Vertaal-knop om een taalvariant te produceren. De vertaalde inhoud wordt hier opgeslagen en kan worden gekopieerd naar elk CPT-bericht vanuit de blokeditor Pattern-inserter of gebruikt als uitgangspunt voor een Gesynchroniseerd patroon (Herbruikbaar blok).','Pattern'=>'Patroon','Post Types'=>'Berichttypen','✓ Translation saved'=>'✓ Vertaling opgeslagen','View'=>'Bekijken','Template Parts'=>'Sjabloononderdelen','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Taal-specifieke kopieën van de sjabloononderdelen van het thema. Zodra ze zijn opgebouwd, worden sjablonen bijgewerkt om te verwijzen naar het taal-specifieke onderdeel.','Re-create all'=>'Alles opnieuw aanmaken','Translate all'=>'Vertaal alles','Fix all links'=>'Repareer alle links','Fix all navs'=>'Alle navigaties repareren','Part'=>'Onderdeel','Status / Actions'=>'Status / Acties','Create'=>'Aanmaken','Templates'=>'Sjablonen','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'FSE-sjablonen gezaaid vanuit het actieve thema. Maak ze aan en pas ze aan in de Site Editor.','Create missing'=>'Maak ontbrekend aan','Fix all parts'=>'Repareer alle onderdelen','SEO'=>'SEO','Multilingual SEO'=>'Meertalige SEO','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Configureer hreflang, Open Graph, Schema.org, sitemaps en sociale delen voor elke taal op je site. Elk gedeelte hieronder behandelt één aspect van meertalige SEO.','Open Graph &amp; Twitter Cards'=>'Open Graph &amp; Twitter Cards','Schema.org'=>'Schema.org','Sitemap'=>'Sitemap','Analysis'=>'Analyse','Compatibility'=>'Compatibiliteit','System'=>'Systeem','Overview'=>'Overzicht','Lingua Forge Settings'=>'Lingua Forge-instellingen','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge voegt meertalige routing, AI-gestuurde vertaling, hreflang SEO-tags en een taalomschakelaar toe aan je WordPress-site.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Gebruik de tabbladen bovenaan deze pagina om elk gebied te configureren. Wijzigingen in het Router-tabblad worden onmiddellijk doorgevoerd; wijzigingen in AI-sleutels en modelinstellingen gelden voor de volgende AI-aanvraag.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Na het wijzigen van de URL-structuurinstellingen (padvoorvoegsel ↔ subdomein), bezoek altijd Instellingen → Permalinks en klik op Wijzigingen opslaan om de herschrijfregels te verversen.','AI Provider Tab'=>'AI Provider Tab','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'Ondersteunde providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Selecteer de actieve provider uit de dropdown — slechts één provider wordt tegelijk gebruikt. Voer een API-sleutel in voor die provider om AI-functies in te schakelen.','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Sleutels worden in rust versleuteld met AES-256-GCM met een sitespecifiek geheim (LINGUAFORGE_SECRET). Deel geen database-exporten zonder eerst het geheim te roteren.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI-functies zijn optioneel. Taalroutering, hreflang, de taalomschakelaar en het vertaalgroep-systeem werken allemaal zonder dat er een provider is geconfigureerd.','Model tiers'=>'Model niveaus','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge gebruikt twee modelniveaus per provider:','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Licht: gebruikt voor meta-beschrijvingen en samenvattinggeneratie — snel, lage kosten.','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Kwaliteit: gebruikt voor berichtvertaling en inhoudsgeneratie — hogere kwaliteit, hogere kosten.','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Laat een modelveld leeg om de ingebouwde standaard voor dat niveau te gebruiken. De placeholder toont welk model wordt gebruikt.','Translation Limits & Behavior'=>'Vertaallimieten & gedrag','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Vertaallimieten: bepaal welke gebruikersrollen AI-vertaling kunnen activeren, en stel een maandbudget in tokens in. Overschrijding van het budget onderbreekt AI-aanroepen totdat de maand is afgelopen.','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Gedrag: kies de AI-voorinstelling (Letterlijk, Gebalanceerd, Creatief), voeg site-brede aangepaste prompt-instructies toe, schakel automatische post-opslag vertaling in of uit, en configureer het Vertaalgeheugen.','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Vertaalgeheugen cachet AI-resultaten op basis van inhouds-hash, taalpaar, provider en model. Het bewerken van een bericht maakt de cache-invoer ongeldig, zodat de volgende vertaling een verse resultaat krijgt.','Router Tab'=>'Router tabblad','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Primaal taal: de taal waarin je bestaande inhoud is geschreven. Alle vertalingen worden uit deze taal geproduceerd; het wijzigen ervan verplaatst of verwijdert geen berichten.','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL-structuur: pad-prefix modus (example.com/de/) vereist geen serverwijzigingen. Subdomein modus (de.example.com) vereist een wildcard DNS-record, een wildcard SSL-certificaat, en een wijziging in de webserverconfiguratie — zie de Server Setup gids.','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Actieve talen: voeg elke taal toe die je wilt ondersteunen. Elke taal krijgt een URL-prefix of subdomein en een hreflang-tag in de &lt;head&gt; van de pagina.','WP site language requirement'=>'Vereiste voor WP-site taal','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'De taal van de WordPress-site (Instellingen → Algemeen → Site-taal) moet op een van de talen staan die je gebruikt voor de inhoud — of de primaire inhoudstaal of een van de secundaire talen. Het mag geen taal zijn zonder inhoud op de site.','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'Voorbeeld van een ondersteunde configuratie: WP-site taal = CA (Catalaans), inhoudstalen = CA + ES.','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'Voorbeeld van een niet-ondersteunde configuratie: WP-site taal = EN (Engels), inhoudstalen = alleen CA + ES. Engels is geen inhoudstaal, dus Lingua Forge kan de WP-locale niet koppelen aan een vertaalgroep.','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'Wanneer de WP-site taal geen inhoudstaal is: WooCommerce-productquery\'s geven nul resultaten op alle catalogusblokken; toewijzing van productafbeeldingen faalt; alle inhoudsquery\'s met taalfilter breken; de taalomschakelaar kan een valse niet-inhoudstaaloptie tonen. Als je een rode configuratiewaarschuwing ziet bovenaan het Router- of Systeemtabblad, corrigeer dan eerst de site-taal.','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE-localisatie: schets, vertaal en herstel links in Full Site Editing-sjablonen en sjabloononderdelen rechtstreeks vanaf dit tabblad.','Glossary Tab'=>'Woordenlijst tabblad','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Pin termen die niet vertaald mogen worden of altijd op een specifieke manier moeten worden weergegeven (bijv. merknamen, productnamen, afkortingen). Woordenlijstbeperkingen worden in elke AI-vertaling aangebracht voor alle functies: berichtvertaling, meta-beschrijving, samenvatting en FSE-sjabloonvertaling.','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Voeg één term per regel toe. Zowel de bronterm als de doelweergave zijn vereist. De taalcombinatie bepaalt op welke vertaalopdrachten de beperking van toepassing is.','SEO Tab'=>'SEO-tabblad','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge is een complete meertalige SEO-oplossing. Geen extra SEO-plugin of sitemap-plugin nodig.','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Wat LF biedt: hreflang-tags voor elke geconfigureerde taal, Open Graph en Twitter Card-tags met og:locale en og:locale:alternate, Schema.org JSON-LD met inLanguage-annotaties, en een speciale meertalige sitemap op /lf-sitemap.xml met xhtml:link alternatieve vermeldingen voor alle vertaalgroepen.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'De sitemap wordt automatisch aangekondigd in robots.txt. Alle grote zoekmachines — Google, Bing, Yandex — ontdekken het via robots.txt. Handmatige indiening is niet nodig.','SEO plugins and conflict avoidance:'=>'SEO-plugins en conflictoplossing:','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Als je Yoast SEO, Rank Math, All in One SEO of SEOPress hebt geïnstalleerd, detecteert Lingua Forge ze en past zich aan om dubbele output te voorkomen. Voor hreflang neemt LF volledig over en onderdrukt de output van de plugin omdat die plugins geen correcte hreflang kunnen produceren voor een meertalige routeringsconfiguratie. Voor Open Graph voegt LF alleen og:locale en og:locale:alternate toe — de meertalige signalen die de plugin niet kan leveren — en laat de basis OG-set aan de plugin over. Voor Schema.org schakelt LF zijn eigen output volledig uit om conflicterende JSON-LD-grafieken te voorkomen.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'Het tabblad SEO → Compatibiliteit toont de live detectiestatus en legt precies uit wat LF doet voor elk functiegedeelte.','SEO Scores'=>'SEO Scores','SEO Score System'=>'SEO Score Systeem','Score computation'=>'Scoreberekening','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Elke post wordt beoordeeld van 0–100 op basis van zes regelgebaseerde metrics: titel, meta beschrijving, woordtelling, kopstructuur, afbeeldingsalt-dekking en interne links. Tien punten worden altijd toegekend voor leestijd (alleen informatief). De resterende 90 punten worden verdeeld over de andere metrics met gewichten die variëren per inhoudsprofiel (zie hieronder).','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Elke metriek geeft een van vier statussen: ok (volledige gewicht), waarschuwing (50% van het gewicht), falen (0), of info (0, geen straf). Een score ≥ 80 is groen, 50–79 amber, onder 50 rood.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Regels voor score van titels (alle profielen): falen als leeg; waarschuwen bij minder dan 10 tekens; waarschuwen bij slechts één woord; waarschuwen als langer dan de SERP-limiet van het profiel (60 tekens voor Blog, 70 voor Product/Landing); ok als minimaal 10 tekens, minimaal 2 woorden, en binnen de SERP-limiet.','Content profiles and weights'=>'Inhoudsprofielen en gewichten','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'Profielen passen drempels en gewichten aan op basis van het type inhoud dat wordt geanalyseerd. Het profiel wordt automatisch bepaald; je kunt het per analyse uitvoeren overschrijven via de profielkeuzelijst.','Blog / Editorial (default)'=>'Blog / Redactie (standaard)','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Titel 15 pts · Meta beschrijving 20 pts · Woordtelling 15 pts · Koppen 20 pts · Afbeeldingen 10 pts · Links 10 pts. Titel SERP-limiet 60 tekens; meta 120–210 tekens; woordtelling waarschuwt onder 300, faalt onder 100; H2 vereist; interne links vereist.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'Automatisch gedetecteerd voor WooCommerce-producten. Titel 20 pts · Meta beschrijving 30 pts · Woordtelling 15 pts · Koppen 5 pts · Afbeeldingen 20 pts · Links 0 pts. Titel SERP limiet 70 tekens; woordtelling waarschuwt onder 80, faalt onder 40; H2 en interne links optioneel.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Automatisch gedetecteerd voor de statische voorpagina; kan handmatig worden geselecteerd. Titel 20 pts · Meta beschrijving 30 pts · Woordtelling 15 pts · Koppen 10 pts · Afbeeldingen 15 pts · Links 0 pts. Titel SERP limiet 70 tekens; woordtelling waarschuwt onder 150, faalt onder 60; H2 en interne links optioneel.','Heading structure rules'=>'Regels voor kopstructuur','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'Exact één H1 is vereist. De H1 is normaal de posttitel die door het thema wordt weergegeven — het wordt gelezen van de live weergegeven pagina indien mogelijk, en van de postinhoud als fallback.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'Wanneer het Blog-profiel een H2 vereist en er geen wordt gevonden, controleert de analyzer eerst op H3-subkoppen voordat een waarschuwing wordt gegeven. Accordion- en Details-blokken gebruiken standaard H3 voor hun koppen; die H3\'s worden geaccepteerd als geldige structuur en geven een ok-resultaat, geen waarschuwing.','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'Korte inhoud (3 paragrafen of minder) wordt nooit bestraft voor het ontbreken van subkoppen, ongeacht het profiel. Een beknopte pagina profiteert niet van een gedwongen kopstructuur.','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'Behandel H2 als H1 gelijkwaardig (Instellingen → SEO → Analyse): schakel dit in wanneer je thema de berichttitel binnen een H2 weergeeft in plaats van een H1. De analyzer promoot de eerste H2 naar H1 zodat de score niet onterecht wordt bestraft.','Score history and badges'=>'Scoregeschiedenis en badges','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Elke keer dat een post wordt geanalyseerd, wordt de score opgeslagen in de post meta. De kolom Taal in de postlijst toont een kleurgecodeerde "SEO N" badge voor elke post die minstens één keer is geanalyseerd. Wanneer twee scores worden opgeslagen, toont een delta-indicator (↑N / ↓N) de verandering sinds de vorige run.','AI Usage & Cache Tab'=>'AI Usage & Cache Tab','Token usage'=>'Tokengebruik','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'De gebruikstabel toont AI-tokenverbruik opgesplitst per functie (vertaling, meta-beschrijving, excerpt, FSE-sjabloon, batchanalyse), provider en model. Gebruik de datumbereikknoppen om te filteren op vandaag, afgelopen 7 dagen, afgelopen 30 dagen of alles.','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'Het dagelijkse quota (geconfigureerd in Gedrag → Limieten) wordt hier bijgehouden. Wanneer het quota is bereikt, worden AI-aanroepen voor de rest van de dag onderbroken. De tabel toont hoeveel van het quota is verbruikt.','Translation caching'=>'Vertaalcache','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forge gebruikt twee onafhankelijke cachelagen om overbodige AI API-aanroepen te verminderen:','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'Slaat ruwe AI-antwoorden op, gekoppeld aan inhouds-hash, taalpaar, provider, model en preset. Cache-items worden automatisch ongeldig gemaakt wanneer de inhoud van de bronpost verandert. Wis individuele post-items of de hele cache vanaf dit tabblad.','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'Slaat de volledige vertaalde postoutput per inhouds-hash op. Opt-in (ingeschakeld in Gedrag). Versnelt herhaalde vertalingen van ongewijzigde inhoud. Wis het hier wanneer je een verse AI-pass wilt forceren, ongeacht of de inhoud is gewijzigd.','Maintenance Tab'=>'Onderhoud tabblad','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Taaloverschrijvingen: beheer aangepaste .po/.mo-overschrijvingsbestanden voor de Lingua Forge UI-strings. Gebruik dit in plaats van het direct bewerken van plugin-bestanden — overschrijvingen blijven bestaan na updates.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Foutopsporing: schakel het foutopsporingslog in om AI-prompts en API-antwoorden vast te leggen in een lokaal bestand. Schakel uit na probleemoplossing — de foutopsporingsmodus schrijft een bestand bij elk AI-verzoek.','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'Verwijderingsgedrag: bepaalt wat wordt verwijderd wanneer de plugin wordt verwijderd via Plugins → Geïnstalleerde plugins → Verwijderen. Plugin-instellingen en AI-caches worden altijd verwijderd. Taaltoewijzingen, vertaalrelaties, meta-beschrijvingen, woordenlijst en Vertaalgeheugen blijven standaard behouden zodat een per ongeluk verwijdering of herinstallatie kan worden hervat. Schakel "Verwijder inhoudsgegevens bij deïnstallatie" alleen in wanneer je volledig meertalige ondersteuning van de site verwijdert — dit kan niet ongedaan worden gemaakt.','System Tab'=>'Systeem Tab','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'Lezen-only diagnostiek voor de huidige installatie. Er worden hier geen instellingen gewijzigd — gebruik het om de configuratie te verifiëren, problemen te ontdekken en informatie te verzamelen voor bugrapporten.','Sections'=>'Secties','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Lingua Forge, WordPress- en PHP-versies; actief thema; URL-structuur; WP-site taal en primaire inhoudstaal. Een rood indicator naast de WP-site taal betekent dat het niet een van de actieve inhoudstalen is — los het op in Instellingen → Algemeen voordat je verdergaat.','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'Actieve provider, geconfigureerde sleutels, modelniveau-keuzes, preset en dagelijkse quota.','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'Bevestigt dat de permalink-structuur compatibel is met Lingua Forge padroutering. Eenvoudige en numerieke structuren worden niet ondersteund.','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'Lijst van actieve third-party SEO-plugins. Lingua Forge past zijn output aan wanneer deze aanwezig zijn — zie Instellingen → SEO → Compatibiliteit voor de per-functie uitsplitsing.','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'WooCommerce-versie, opslagmodus voor bestellingen (CPT / HPOS / gedeeld), en een tabel met vertaaldekking per taal voor de vier ingebouwde WC-pagina\'s (Winkel, Winkelwagen, Afrekenen, Mijn account).','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'Lijst van berichttypen die gepubliceerde berichten hebben zonder een _lf_lang meta-waarde. Berichten zonder dit label zijn onzichtbaar voor alle taalfilters. Gebruik de Repareren-knop om ze te labelen met de brontaal, of Sluiten om het berichttype volledig uit de taalroutering te verwijderen.','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'Inklapbare dump van alle door LF beheerde items in $wp_rewrite->extra_rules_top. Handig voor het diagnosticeren van 404-fouten of routeringsconflicten na het toevoegen van een nieuwe taal.','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'Eén-klik kopie van een platte tekst systeemoverzicht dat alles van bovenstaande secties bevat. Plak dit in een GitHub-issue of supportverzoek zodat de volledige omgeving in één oogopslag zichtbaar is.','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'Heb je een bug of onverwacht gedrag gevonden? Open dan een issue op GitHub — voeg de Debug Info-blok hierboven toe en een korte beschrijving van wat je verwachtte versus wat er gebeurde.','Open an issue →'=>'Open een issue →','Getting started'=>'Aan de slag','Server setup (subdomain)'=>'Serverinstelling (subdomein)','Translation workflow'=>'Vertaalworkflow','Language switcher'=>'Taalomschakelaar','WP-CLI reference'=>'WP-CLI referentie','Integration API'=>'Integratie API','Documentation'=>'Documentatie','Report an issue on GitHub'=>'Meld een probleem op GitHub','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','WordPress AI Client (WP 7.0+)'=>'WordPress AI Client (WP 7.0+)','Meta Description, Excerpt Generator'=>'Meta Beschrijving, Uittreksel Generator','Translation, Content Generator'=>'Vertaling, Inhoudsgenerator','Testing…'=>'Bezig met testen…','✓ Connection OK'=>'✓ Verbinding OK','✗ Failed:'=>'✗ Mislukt:','No response from provider — check the error log for details.'=>'Geen reactie van de provider — controleer het foutlog voor details.','Network error — could not reach the WordPress AJAX endpoint.'=>'Netwerkfout — kon de WordPress AJAX-eindpunt niet bereiken.','Translating a real post with this model…'=>'Een echte post vertalen met dit model…','preset'=>'preset','Loading…'=>'Laden…','Installing…'=>'Installeren…','✓ Language installed.'=>'✓ Taal geïnstalleerd.','✗ Error:'=>'✗ Fout:','Creating…'=>'Bezig met maken…','✓ All templates created.'=>'✓ Alle sjablonen gemaakt.','Some templates could not be created.'=>'Sommige sjablonen konden niet worden gemaakt.','Recreating…'=>'Bezig met opnieuw aanmaken…','✓ All templates recreated.'=>'✓ Alle templates opnieuw aangemaakt.','Some templates could not be recreated.'=>'Sommige templates konden niet opnieuw worden aangemaakt.','This overwrites this template with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Dit overschrijft deze template met een schone kopie van het actieve thema, en verwijdert eventuele aanpassingen die in de Site Editor zijn gemaakt. Dit kan niet ongedaan worden gemaakt. Doorgaan?','This overwrites every template with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Dit overschrijft elke template met een schone kopie van het actieve thema, en verwijdert eventuele aanpassingen die in de Site Editor zijn gemaakt. Dit kan niet ongedaan worden gemaakt. Doorgaan?','✓ All parts recreated.'=>'✓ Alle onderdelen opnieuw aangemaakt.','Some parts could not be recreated.'=>'Sommige onderdelen konden niet opnieuw worden aangemaakt.','This overwrites this template part with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Dit overschrijft dit templateonderdeel met een schone kopie van het actieve thema, en verwijdert eventuele aanpassingen die in de Site Editor zijn gemaakt. Dit kan niet ongedaan worden gemaakt. Doorgaan?','This overwrites every template part with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Dit overschrijft elk templateonderdeel met een schone kopie van het actieve thema, en verwijdert eventuele aanpassingen die in de Site Editor zijn gemaakt. Dit kan niet ongedaan worden gemaakt. Doorgaan?','✓ All parts created.'=>'✓ Alle onderdelen gemaakt.','Some parts could not be created.'=>'Sommige onderdelen konden niet worden gemaakt.','✓ All translated.'=>'✓ Alles vertaald.','Some translations failed.'=>'Sommige vertalingen zijn mislukt.','Review carefully — links and slugs not updated.'=>'Bekijk het zorgvuldig — links en slugs niet bijgewerkt.','Fixing…'=>'Bezig met repareren…','✓ Links fixed.'=>'✓ Links gerepareerd.','Some link fixes failed.'=>'Sommige linkreparaties zijn mislukt.','✓ Parts fixed.'=>'✓ Onderdelen gerepareerd.','Some part fixes failed.'=>'Sommige onderdeelreparaties zijn mislukt.','✓ Nav refs fixed.'=>'✓ Navigatieverwijzingen gerepareerd.','Some nav ref fixes failed.'=>'Sommige navigatieverwijzingen reparaties zijn mislukt.','✓ Pattern translated.'=>'✓ Patroon vertaald.','Pattern translation failed.'=>'Patroonvertaling mislukt.','Hide'=>'Verberg','Re-create all templates'=>'Alle templates opnieuw aanmaken','Re-create all parts'=>'Alle onderdelen opnieuw aanmaken','This runs Re-create all templates, Re-create all parts, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time. It overwrites existing templates and parts with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template and part, which may take a while and may incur cost depending on your provider. Continue?'=>'Dit voert Alle templates opnieuw aanmaken, Alle onderdelen opnieuw aanmaken, Alles vertalen, Alle onderdelen repareren en Alle koppelingen repareren uit voor elk van uw {total} actieve talen, telkens één taal tegelijk. Bestaande templates en onderdelen worden overschreven met schone kopieën van het actieve thema (waarbij aanpassingen in Site Editor worden verwijderd) en inhoud wordt opnieuw vertaald — geen hiervan kan ongedaan worden gemaakt. Alles vertalen voert echte AI API-aanroepen uit voor elk template en onderdeel, wat enige tijd kan duren en afhankelijk van uw provider kosten met zich mee kan brengen. Doorgaan?','This runs Re-create all templates, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time — template parts (headers, footers, etc.) are left untouched. It overwrites existing templates with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template, which may take a while and may incur cost depending on your provider. Continue?'=>'Dit voert Alle templates opnieuw aanmaken, Alles vertalen, Alle onderdelen repareren en Alle koppelingen repareren uit voor elk van uw {total} actieve talen, telkens één taal tegelijk — templateonderdelen (headers, voetlijsten, enz.) blijven ongewijzigd. Bestaande templates worden overschreven met schone kopieën van het actieve thema (waarbij aanpassingen in Site Editor worden verwijderd) en inhoud wordt opnieuw vertaald — geen hiervan kan ongedaan worden gemaakt. Alles vertalen voert echte AI API-aanroepen uit voor elk template, wat enige tijd kan duren en afhankelijk van uw provider kosten met zich mee kan brengen. Doorgaan?','This runs Re-create all parts (headers, footers, and every other template part) for every one of your {total} active languages, one language at a time. It overwrites existing template parts with fresh copies from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Dit voert Alle onderdelen opnieuw aanmaken (headers, voetlijsten en elk ander templateonderdeel) uit voor elk van uw {total} actieve talen, telkens één taal tegelijk. Bestaande templateonderdelen worden overschreven met schone kopieën van het actieve thema, en eventuele aanpassingen in Site Editor worden verwijderd. Dit kan niet ongedaan worden gemaakt. Doorgaan?','Starting…'=>'Bezig met starten…','Processing {lang} ({index} of {total}) — {step}…'=>'Bezig met verwerken van {lang} ({index} van {total}) — {step}…','Cancelled.'=>'Geannuleerd.','{done} of {total} languages processed.'=>'{done} van {total} talen verwerkt.','⚠ Done with issues.'=>'⚠ Voltooid met problemen.','✓ All {total} languages processed.'=>'✓ Alle {total} talen verwerkt.','Built-in preset instructions:'=>'Ingebouwde preset-instructies:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Geen ingebouwde instructies — elke AI-functie gebruikt zijn eigen afgestemde standaardinstellingen. Vul het veld \'Aangepaste prompt-instructies\' hieronder in om je eigen site-brede regels toe te voegen.','Modified'=>'Gewijzigd','edit'=>'bewerken','No published posts found for the selected filters.'=>'Geen gepubliceerde berichten gevonden voor de geselecteerde filters.','Just now'=>'Zojuist','Score'=>'Score','Source title'=>'Bron titel','Multilingual SEO overview'=>'Overzicht meertalige SEO','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'Scores zijn een signaal, geen oordeel. Sommige inhoud is structureel beperkt — zeer korte pagina\'s, landingspagina\'s met weinig hoofdtekst, of pagina\'s waarvan het doel navigatie is in plaats van informatie, kunnen van nature lager scoren. Gebruik dit overzicht om echte parity-verschillen tussen talen te ontdekken, niet om een nummer na te jagen.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'Dit is een WooCommerce-systeempagina (Winkel, Winkelwagen, Afrekenen, enz.). De inhoud wordt beheerd door WooCommerce — de score weerspiegelt alleen structurele signalen, niet door de gebruiker bewerkbare SEO-inhoud.','Settings'=>'Instellingen','You do not have permission to manage these settings.'=>'Je hebt geen toestemming om deze instellingen te beheren.','Lingua Forge — Settings'=>'Lingua Forge — Instellingen','Settings saved.'=>'Instellingen opgeslagen.','Save Settings'=>'Instellingen opslaan','Standard'=>'Standaard','Technical / Scientific'=>'Technisch / Wetenschappelijk','Legal / Compliance'=>'Juridisch / Compliance','Creative / Marketing'=>'Creatief / Marketing','Lingua Forge — AI Usage Statistics'=>'Lingua Forge — AI-gebruiksstatistieken','Lingua Forge AI Usage Statistics'=>'Lingua Forge AI Gebruiksstatistieken','Date'=>'Datum','Request count'=>'Aantal aanvragen','Full Article'=>'Volledig artikel','Introduction only'=>'Alleen introductie','Structured Outline'=>'Gestructureerde schets','Generate Content'=>'Inhoud genereren','Hints'=>'Hints','Key points, ideas, or structure to build from…'=>'Belangrijke punten, ideeën of structuur om vanaf te bouwen…','Tone'=>'Toon','Output'=>'Uitvoer','Generate Excerpt'=>'Fragment genereren','Generate Meta Description'=>'Meta beschrijving genereren','Translate Content'=>'Inhoud vertalen','Mode'=>'Modus','Full post'=>'Volledige bericht','Translate chunk'=>'Chunk vertalen','Target Language'=>'Doeltaal','Text to translate'=>'Tekst om te vertalen','Paste a footnote, sentence, or any snippet here…'=>'Plak hier een voetnoot, zin of fragment…','Also generate meta description'=>'Ook meta beschrijving genereren','Translated Labels'=>'Vertaald labels','Attribute label displayed in this language. Leave empty to use the default label.'=>'Attribuutlabel weergegeven in deze taal. Laat leeg om de standaardlabel te gebruiken.','Translate all labels (AI)'=>'Vertaal alle labels (AI)','Insufficient permissions.'=>'Onvoldoende rechten.','All labels already translated.'=>'Alle labels al vertaald.','%d label(s) translated.'=>'%d label(s) vertaald.','Translation failed. Check the browser console.'=>'Vertaling mislukt. Controleer de browserconsole.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Kan niet schrijven naar product %1$d: het is een vertaalde versie (taal: %2$s)%3$s. Operationele gegevens (prijs, voorraad, SKU, afmetingen) moeten worden bijgewerkt op het bronproduct. Los de bronproduct-ID op via: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Translated Names'=>'Vertaald namen','Name displayed in this language. Leave empty to use the source name.'=>'Naam weergegeven in deze taal. Laat leeg om de bronnaam te gebruiken.','Translate all tags (AI)'=>'Vertaal alle tags (AI)','Translate all categories (AI)'=>'Vertaal alle categorieën (AI)','Translate all %s terms (AI)'=>'Vertaal alle %s-termen (AI)','Translate all terms (AI)'=>'Vertaal alle termen (AI)','Invalid taxonomy.'=>'Ongeldige taxonomie.','No terms found.'=>'Geen termen gevonden.','%d term(s) translated.'=>'%d term(s) vertaald.','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%d al vertaald — <a href="#" class="lf-force-translate">forceer opnieuw vertalen</a>','%1$d translated, %2$d skipped.'=>'%1$d vertaald, %2$d overgeslagen.','Order placed in language: %s'=>'Bestelling geplaatst in taal: %s','Invalid API key — double-check the key entered in the AI Provider settings.'=>'Ongeldige API-sleutel — controleer de ingevoerde sleutel in de AI Provider-instellingen.','Payment required — your account has no remaining credits.'=>'Betaling vereist — je account heeft geen resterende tegoeden.','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'Toegang verboden — je account kan geschorst zijn of de sleutel mist de benodigde rechten.','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'Beperkt — te veel verzoeken naar de provider; wacht even en probeer opnieuw.','Provider service temporarily unavailable — try again in a moment.'=>'De service van de provider is tijdelijk niet beschikbaar — probeer het over een moment opnieuw.','Provider error (HTTP %1$d): %2$s'=>'Fout van de provider (HTTP %1$d): %2$s','Unexpected provider error (HTTP %d).'=>'Onverwachte fout van de provider (HTTP %d).','No API key configured — enter your key in the AI Provider settings.'=>'Geen API-sleutel geconfigureerd — voer je sleutel in bij de AI Provider-instellingen.','Network error — could not reach the provider: %s'=>'Netwerkfout — kon de provider niet bereiken: %s','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'Geen credits meer — vul je OpenAI-account bij op platform.openai.com/account/billing.','WordPress AI Client requires WordPress 7.0 or later.'=>'WordPress AI Client vereist WordPress 7.0 of later.','No user message found in the message array.'=>'Geen gebruikersbericht gevonden in de berichtarray.','No text-generation model is available. Configure an AI provider in Settings → Connectors.'=>'Geen tekstgeneratiemodel beschikbaar. Configureer een AI-provider in Instellingen → Connectors.','Too many AI requests. Please retry in %d seconds.'=>'Te veel AI-verzoeken. Probeer het opnieuw over %d seconden.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Dagelijkse AI-quotum bereikt (%1$d verzoeken). Reset om %2$s UTC.','View Lingua Forge details'=>'Bekijk Lingua Forge-details','View details'=>'Bekijk details','Visit plugin site'=>'Bezoek plugin-site','Lingua Forge update blocked: download host "%s" is not on the allowlist.'=>'Lingua Forge update geblokkeerd: download host "%s" staat niet op de toestemmingslijst.','Lingua Forge update blocked: SHA-256 of the downloaded package does not match the manifest. The file may have been tampered with.'=>'Lingua Forge update geblokkeerd: SHA-256 van het gedownloade pakket komt niet overeen met de manifest. Het bestand kan zijn gemanipuleerd.','Exclude from navigation menus'=>'Uitsluiten van navigatiemenu\'s','Apply to all language versions'=>'Toepassen op alle taalversies','Noindex (hide this language version from search engines)'=>'Noindex (verberg deze taalversie voor zoekmachines)','%d language not yet linked'=>'%d taal nog niet gekoppeld' . "\0" . '%d talen nog niet gekoppeld','This is the source page. Footnotes are edited directly in the block editor.'=>'Dit is de bronpagina. Voetnoten worden direct in de blokbewerker bewerkt.','No source page linked yet.'=>'Nog geen bronpagina gekoppeld.','The source page has no footnotes.'=>'De bronpagina heeft geen voetnoten.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Deze voetnoten komen van de bronpagina en worden hier alleen ter referentie weergegeven. Voeg ze toe aan deze pagina met de blokbewerker.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d gelokaliseerde sjabloon(s) uit het &#8220;%2$s&#8221; thema worden bewaard in de database, maar zijn momenteel inactief. Ze worden weer actief als je dat thema opnieuw activeert. Om je vertalingen over te zetten naar het nieuwe thema, regenerateer ze via <strong>Instellingen → Lingua Forge → Router → FSE-sjabloon</strong>.','Scanning posts for missing or out-of-sync featured images…'=>'Posts scannen op ontbrekende of niet-gesynchroniseerde uitgelichte afbeeldingen…','Re-scanning…'=>'Opnieuw scannen…','Scan failed: '=>'Scan mislukt: ','unknown error'=>'onbekende fout','Scan request failed. Please try again.'=>'Scanverzoek mislukt. Probeer het opnieuw.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Geen <strong>{lang}</strong> berichten gevonden. Zorg dat alle vertaalde berichten hun Taal-meta op <strong>{lang}</strong> hebben staan in de Taal-metabox.','✅ All <strong>{lang}</strong> featured images are already in sync with their source post. Scanned <strong>{scanned}</strong> post(s).'=>'✅ Alle <strong>{lang}</strong> featured images zijn al gesynchroniseerd met hun bronbericht. Gescande <strong>{scanned}</strong> bericht(en).','Found <strong>{n}</strong> post(s) missing or out of sync with their source featured image, out of <strong>{scanned}</strong> scanned for <strong>{lang}</strong>.'=>'Gevonden <strong>{n}</strong> bericht(en) ontbreekt of niet gesynchroniseerd met hun bronafbeelding, uit <strong>{scanned}</strong> gescand voor <strong>{lang}</strong>.','Post'=>'Bericht','Current'=>'Huidige','Source (EN)'=>'Bron (EN)','None'=>'Geen','Copy from source'=>'Kopiëren uit bron','Copying…'=>'Kopiëren…','✅ Copied'=>'✅ Gekopieerd','❌ Failed'=>'❌ Mislukt','Done — {done} of {total} post(s) fixed.'=>'Klaar — {done} van {total} bericht(en) gerepareerd.','Fixing {n} / {total}…'=>'Reparatie van {n} / {total}…','Fix Featured Images'=>'Featured Images repareren','Featured Image Fixer'=>'Featured Image Fixer','Fix All'=>'Alles repareren','Re-scan'=>'Opnieuw scannen','Scanning posts for broken language links…'=>'Posts scannen op gebroken taallinks…','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Geen gebroken links of sjabloonfouten gevonden voor <strong>{lang}</strong>. Gescand <strong>{scanned}</strong> bericht(en) en pagina(\'s) — alle controles geslaagd. Links naar sjabloononderdelen (header, footer, sidebar) zijn hier niet inbegrepen — gebruik de knop Fix Template Parts om die apart te controleren.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> automatisch te repareren link(en)','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> link(s) die handmatige beoordeling vereisen','and'=>'en','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Gevonden {parts} over <strong>{total}</strong> van <strong>{scanned}</strong> gescande bericht(en) voor <strong>{lang}</strong>.','link(s)'=>'link(en)','Fix'=>'Fix','✅ Fixed ({n})'=>'✅ Gerepareerd ({n})','⚠ No changes — re-scan?'=>'⚠ Geen wijzigingen — opnieuw scannen?','⚠ No changes'=>'⚠ Geen wijzigingen','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} had geen vervangbare links — opnieuw scannen om te onderzoeken)','URL could not be mapped to a post — check the link target exists'=>'URL kon niet worden gekoppeld aan een bericht — controleer of de linkdoel bestaat','No {lang} translation registered (TRID missing)'=>'Geen {lang} vertaling geregistreerd (TRID ontbreekt)','Translation found but permalink could not be generated'=>'Vertaling gevonden, maar permalink kon niet worden gegenereerd','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> verouderd(e) pad(pad(en))','📍 Stale path (page moved)'=>'📍 Verouderd pad (pagina verplaatst)','{